        end)
    end

    -- =====================================================
    -- RAID
    -- =====================================================
    do
        local v = makeView("raid")
        gap(v, 6)
        readout(v, function()
            local rd = P.raid
            if not rd then return "-" end
            local rl = rd.loop
            return table.concat({
                "raid      " .. tostring(P.raidNote),
                string.format("done      %d raids  ·  %d relocations%s", rd.done, rd.moves,
