    -- =====================================================
    -- SERVERS & TEAM
    -- =====================================================
    do
        local v = makeView("servers")
        gap(v, 6)
        readout(v, function()
            local el = P.elite
            local t = el.tally
            local avg = (t.joins > 0) and string.format("%.0fs", t.joinSecs / t.joins) or "-"
            return table.concat({
                "now       " .. tostring(el.note),
                string.format("joined    %d   ·   join %s   ·   failed joins %d", t.joins, avg, t.fails),
                "servers   " .. tostring(el.lastList or "not read yet"),
                "last join " .. tostring(el.lastJoin or "none yet"),
                "counting since " .. os.date("%d %b %H:%M", t.since or os.time()),
            }, "\n")
        end)
        heading2(v, "when nothing here is worth it")
        switchRow(v, "Hop to the next server",
            "Off: wait in this one",
            function() return CFG.HuntHop end,
            function(x) CFG.HuntHop = x end)
        radio(v, 122, {
            { "fewest", "Fewest players first", "fewer hunters" },
            { "most",   "Most players first",   "PvP" },
            { "random", "Any order",            "" },
        }, function() return CFG.HopOrder end, function(x) CFG.HopOrder = x end)
        sliderRow(v, "Try a server again after", 5, 60, 1,
            function() return CFG.HopRevisit end,
            function(x) CFG.HopRevisit = x end, " min")
        heading2(v, "your team")
        switchRow(v, "Pick my team on join",
            "The Pirates / Marines screen every new server shows",
            function() return CFG.AutoTeam end,
            function(x) CFG.AutoTeam = x P.teamSave() end)
        radio(v, 82, {
            { "Pirates", "Pirates", "" },
            { "Marines", "Marines", "" },
        }, function() return CFG.Team end, function(x) CFG.Team = x P.teamSave() end)
        readout(v, function() return "team      " .. tostring(P.teamNote) end)
        readout(v, function() return P.reloadWay() end)
        heading2(v, "by hand")
        actionRow(v, "Hop now", nil, function() P.hopNow() end)
        actionRow(v, "Forget the servers looked at", nil, function()
            table.clear(P.elite.visited)
            P.elite.note = "servers looked at: forgotten"
        end)
        actionRow(v, "Reset the hunt counts", nil, function()
            local t = P.elite.tally
            for k in pairs(t) do t[k] = 0 end
            t.since = os.time()
            P.elite.note = "hunt counts reset"
        end)
        fold(v, "How it works", function(v)
            caption(v, "One killed there is back 8 min 45 s later.")
            caption(v, "Your settings, the servers already looked at and these "
                .. "counts go with you. Without queue_on_teleport, the README's "
                .. "three-line loader in the executor's autoexec folder does the same.")
        end)
    end

    -- =====================================================
    -- STATS & DEBUG
    -- =====================================================
    do
        local v = makeView("stats")
        gap(v, 8)
        -- SETTINGS LOCK (user, 2026-10-14): what you set stays after a reload.
        heading2(v, "your settings")
        switchRow(v, "Lock my settings", "On: everything you changed stays after a reload",
            function() return (P :: any).lock ~= nil and (P :: any).lock.on == true end,
            function(x) if (P :: any).lockSet then (P :: any).lockSet(x) end end)
        readout(v, function()
            local k = (P :: any).lock
            return k and tostring(k.note) or "-"
        end)
        heading2(v, "which setup is better")
        readout(v, function()
            local lines = {}
            local m = meas
            if m then
                local kpm = (m.fight > 0) and (m.kills / (m.fight / 60)) or 0
                table.insert(lines, "THIS SETUP")
                table.insert(lines, "   " .. m.key)
                table.insert(lines, string.format("   %.1f kills/min  ·  pile %s  ·  %d piles  ·  %s fighting",
                    kpm, (m.piles > 0) and string.format("%.1fs", m.pileSecs / m.piles) or "-",
                    m.piles, mmss(m.fight)))
            end
            if #tried > 0 then
                table.insert(lines, "")
                table.insert(lines, "TRIED")
                for _, t in ipairs(tried) do
                    table.insert(lines, string.format("   %.1f kills/min  ·  %s  ·  %s",
                        t.kpm, t.avg and string.format("pile %.1fs", t.avg) or "pile -", mmss(t.secs)))
                    table.insert(lines, "      " .. t.key)
                end
            end
            return table.concat(lines, "\n")
        end)
        caption(v, "Change any attack switch or the M1 count and this setup "
            .. "moves to TRIED with its numbers. Only fighting time counts, so "
            .. "flights do not punish a setup. Run each a few minutes on the "
            .. "same camp.")
        actionRow(v, "Clear the tried list", nil, function() table.clear(tried) end)
        heading2(v, "counters")
        readout(v, function()
            local mins = math.max((os.clock() - stats.startedAt) / 60, 1 / 60)
            return table.concat({
                string.format("state       %s   %.0fs", state, os.clock() - stateEnteredAt),
                "target      " .. tostring(activeName or "-"),
                "in hand     " .. tostring(P.heldTool() or "-"),
                "kills       " .. stats.kills .. string.format("   %.1f/min overall", stats.kills / mins),
                "piles       " .. stats.piles,
                "M1          " .. stats.m1 .. "   skills " .. stats.casts
                    .. string.format(" (%d fired, %d hit, %d did not fire)", stats.castsTook,
                        stats.castsHit, stats.castsMissed)
                    .. "   swaps " .. stats.swaps,
                "probes      " .. stats.probes .. "   (M1 ways tried)",
                "travel      " .. stats.flights .. " flights   " .. stats.hops .. " hops   "
                    .. stats.pulledBack .. " pulled back",
                "magnet      held " .. tostring(P.pileHeld) .. "   put back " .. stats.putBack,
                "escapes     " .. stats.escapes,
                "haki        " .. stats.hakiPresses .. "   (J/E presses)",
                "status      " .. statusLine,
            }, "\n")
        end)
        actionRow(v, "Reset the counters", nil, function()
            for k in pairs(stats) do stats[k] = 0 end
            stats.startedAt = os.clock()
            say("counters reset")
        end)
        hairline(v)
        switchRow(v, "Print debug to the console", nil,
            function() return CFG.Debug end,
            function(x) CFG.Debug = x end)
        gap(v, 8)
        actionRow(v, "Stop and close the panel", "danger", function()
            P.stop()
            if gui then gui:Destroy() end
        end)
    end

    show("home")

    task.spawn(function()
        while gui and gui.Parent do
            dot.BackgroundColor3 = P.running and C.live or C.third
            for _, e in ipairs(live) do
                if (not e.v or e.v.Visible) and (not e.w or e.w.Visible) then pcall(e.f) end
            end
            task.wait(0.3)
        end
    end)
end

-- The panel. A failure is SAID now - it used to vanish inside a pcall (no
-- panel, not a word). _G.BFF.panel() builds it again, from the console.
function P.panel()
    local ok, e = pcall(buildUI)
    if not ok then warn("[BFF] the panel failed to build: " .. tostring(e)) end
    return ok
end

-- =========================================================
-- API
-- =========================================================
function P.start()
    -- No mode on (user, 2026-10-12): nothing to run - nothing starts.
    if not (CFG.Circuit or CFG.Hunt or CFG.RandomMode or CFG.RaidMode or CFG.LeviFight or CFG.Volcano) then
        say("no mode on - pick one in Modes")
        print("[BFF] no mode on - nothing started")
        return
    end
    if P.running then P.stop() end
    -- PvP and the farm both drive your character and the aim: one at a time.
    if P.pvp and P.pvp.on then pcall(P.pvpSet, false) end
    for k in pairs(stats) do stats[k] = 0 end
    stats.startedAt = os.clock()
    activeName, countedDead, circuitIdx = nil, {}, 1
    releasePile()
    table.clear(pileWatch)
    lockCF, lastWritten, flying = nil, nil, false
    P.handsOff = false
    wantPose = "safe"
    P.running   = true
    moveEnabled = true
    pcall(syncWeapons)
    rollMeas()

    -- Haki: as farm_pro. Enhancement off at start = a fresh life, both go
    -- back on; otherwise Observation gets its timed look straight away.
    seenChar, seenCharAt = player.Character, os.clock() - 10
    busoTries = 0
    P.kenDone = false
    kenNextAt, kenVerifyAt, kenMisses, kenBlind = 0, nil, 0, false
    if CFG.AutoBuso and not hasBuso() then
        kenChar = nil
    else
        kenChar = player.Character
    end

    track(RunService.Stepped:Connect(function() pcall(bodyStepped) end))
    track(RunService.Heartbeat:Connect(function(dt)
        pcall(bodyHeartbeat)
        pcall(magnetTick)
        if P.running and os.clock() < aimUntil then
            -- A point of its own (a volcano vent): always aimed at, hidden.
            if P.aimAt then
                pcall(aimSwapIn, P.aimAt, P.aimAt)
            elseif CFG.AimSkills and CFG.AimHidden and pileCentre then
                pcall(aimSwapIn, aimPoint(), pileCentre)
            end
        end
        if attacking and meas then meas.fight += dt end
        pcall((P :: any).gunWatch)
        pcall((P :: any).silentTick, P.aimTarget() ~= nil)
    end))
    -- The aim lock: after the camera scripts, every frame the pile is hit.
    pcall(hiddenAim, true)
    pcall(function() RunService:UnbindFromRenderStep("BFFAim") end)
    pcall(function()
        RunService:BindToRenderStep("BFFAim", Enum.RenderPriority.Camera.Value + 1, function()
            if P.running and attacking and CFG.AimSkills and not CFG.AimHidden and pileCentre then
                aimCamera(aimPoint(), pileCentre)
            end
        end)
    end)
    track(player.Idled:Connect(function()
        pcall(function()
            VirtualUser:CaptureController()
            VirtualUser:ClickButton2(Vector2.new())
        end)
    end))
    track(player.CharacterAdded:Connect(function()
        releasePile()
        attacking = false
        releaseCamera()
    end))
    if not (gui and gui.Parent) then P.panel() end

    task.spawn(mainLoop)
    task.spawn(sideLoop)
    print("[BFF] running - build " .. tostring(P.build) .. ". _G.BFF.stop() to halt.")
end

-- why = "reload": a new copy of the script is replacing this one (the top of
-- the file) -- not you stopping, so a hunt carried over a hop stays carried.
function P.stop(why)
    if why ~= "reload" then pcall(P.carryOff) end
    -- A new copy replacing this one: PvP's view switch, screen and
    -- attributes are given back first (the new copy starts with PvP off).
    if why == "reload" then pcall(P.pvpSet, false) end
    P.running = false
    epoch += 1                 -- everything in flight gives up on this line
    moveEnabled = false
    task.delay(0.3, function() moveEnabled = true end)
    releasePile()
    attacking, flying = false, false
    lockCF, lastWritten = nil, nil
    pcall(function() RunService:UnbindFromRenderStep("BFFAim") end)
    aimUntil = 0
    P.aimAt = nil
    pcall((P :: any).gunRelease)
    P.gunFocus = nil
    pcall((P :: any).silentOff)
    task.spawn(function() pcall((P :: any).rotRestore) end)
    if P.sea then P.sea.driving = false end    -- the boat stops; you stay in your seat
    P.handsOff = false
    pcall(hiddenAim, false)
    pcall(releaseCamera)
    for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
    table.clear(conns)
    pcall(restoreBody)
    setState("IDLE")
    say("stopped")
    print(string.format("[BFF] stopped. kills=%d piles=%d", stats.kills, stats.piles))
end

function P.stats() return stats end
function P.state() return state, statusLine end

-- =========================================================
-- THE TEAM
-- =========================================================
-- Every join asks Pirates or Marines before your character spawns -- so
-- every hop does. Picked for you (CFG.AutoTeam, CFG.Team): CommF_("SetTeam",
-- team), as the public hubs do (2026-04 .. 2026-09-29), every 2 s until you
-- are on one. Only while you have no team: the one you are on is never
-- switched. NOT the screen's own button through getconnections -- firing a
-- game's connections natively is the one call here an executor can crash
-- on (removed 2026-09-30 while client crashes on join were being traced).
P.teamNote = "not needed yet"
function P.pickTeam()
    P.teamLoad()
    while _G.BFF == P and player.Team == nil do
        local team = CFG.Team
        if CFG.AutoTeam and (team == "Pirates" or team == "Marines") then
            local cf = commF()
            if cf then pcall(function() cf:InvokeServer("SetTeam", team) end) end
            task.wait(2)
            P.teamNote = (player.Team == nil) and ("asking for " .. team .. " ...") or P.teamNote
        else
            P.teamNote = "choose your team - picking it is off"
            task.wait(1)
        end
    end
    if player.Team then
        P.teamNote = "on " .. player.Team.Name
        -- The team is set; its screen is not needed (the remote does not
        -- always close it).
        pcall(function()
            local ct = player.PlayerGui.Main.ChooseTeam
            if ct.Visible then ct.Visible = false end
        end)
    end
end

-- YOUR PICK IS KEPT (user, 2026-10-24: Marines picked, every hop still
-- joined Pirates). autoexec_team.lua asks the moment a server loads, seconds
-- before this script is back from the queued reload, and a team once set is
-- never switched -- so its own TEAM ("Pirates") always won. Now the pick is
-- a file per account, written whenever you change it on Servers & team and
-- read at every load, here and by the autoexec: the last team you picked is
-- the one every join asks for, settings lock or not.
P.teamFile = "bff_team_" .. tostring(player.UserId) .. ".json"
function P.teamSave()
    if not writefile then return end
    pcall(function()
        writefile(P.teamFile, game:GetService("HttpService"):JSONEncode({
            team = CFG.Team, pick = CFG.AutoTeam and true or false }))
    end)
end
-- Your kept pick into CFG. None kept yet: this load's (carried, locked or
-- default) becomes it, so the autoexec has one from the next join on.
function P.teamLoad()
    local ok, t = pcall(function()
        return game:GetService("HttpService"):JSONDecode(readfile(P.teamFile))
    end)
    if ok and type(t) == "table" and (t.team == "Pirates" or t.team == "Marines") then
        CFG.Team = t.team
        if type(t.pick) == "boolean" then CFG.AutoTeam = t.pick end
    else
        P.teamSave()
    end
end

-- =========================================================
-- SILENT AIM
-- =========================================================
-- The camera swap points the line through your cursor at the target, but a
-- skill that reads the mouse itself still went where the cursor was (user,
-- the volcano, 2026-10-04). So, while P.aimTarget() names a point (only while
-- this script fires), Mouse.Hit / Target / X / Y / UnitRay answer for the
-- target. The script's own reads (checkcaller) are left alone.
--
-- ONLY __index, and ONLY while casting (user, the same day: NPCs invisible,
-- the sea's darkness gone). The first version also hooked __namecall, for
-- the whole session: every WaitForChild / InvokeServer of every game script
-- went through it, and where the executor's newcclosure cannot yield those
-- scripts died - the NPC loader and the sea's lighting among them. Now the
-- hook goes in when a cast starts and the original goes back 3 s after the
-- last one (and on stop) - nothing of the game's runs through it otherwise.
do
    local function build()
        local IDLE_OFF = 3
        local oldIndex = nil      -- the game's own __index while ours is in
        local lastWant = 0

        local function canHook() return hookmetamethod ~= nil end
        P.silentHooked = function() return oldIndex ~= nil end

        if _G.BFF_SILENT_HOOKED and not _G.BFF_SILENT_V2 then
            -- An older copy's whole-session hook is still in this game, and
            -- it cannot be taken out from here.
            P.silentNote = "an old copy's hook is still in this game - REJOIN (it hides NPCs and the sea's darkness)"
            print("[BFF] " .. P.silentNote)
        elseif not canHook() then
            P.silentNote = "this executor cannot hook calls - the camera aim only"
        else
            P.silentNote = "ready (hooks only while casting)"
        end
        _G.BFF_SILENT_V2 = true

        -- kind (PvP, 2026-10-13): "skill" = the game's skill-aim table (the
        -- server runs the move: aimed ahead), "gun" = your mouse (a gun's
        -- shot: a ray at what you see, or the server's slow projectile).
        local function aimNow(kind)
            -- PvP (2026-10-11): the player you fight, whatever YOU fire.
            if P.pvp and P.pvp.on then
                if not CFG.PvpAim then return nil end
                local ok, t = pcall(P.pvp.aimPoint, kind)
                return ok and t or nil
            end
            if not (P.running and CFG.SilentAim) then return nil end
            local ok, t = pcall(P.aimTarget)
            return ok and t or nil
        end

        -- THE GAME'S OWN SKILL AIM (2026-10-09, read in the decompiled client
        -- v4623). Skills, and a fruit's M1 (sent as the key G), never read
        -- your PlayerMouse: MovesetClientRunner's sendMouse does
        -- RemoteEvent:FireServer(Mouse.Hit.Position) with Mouse =
        -- require(ReplicatedStorage.Mouse) - a plain table the game aims
        -- again every frame (a ray from the camera through the cursor). The
        -- hook on the PlayerMouse below reached guns only (CombatController's
        -- shot reads the PlayerMouse). Here, while this script casts, that
        -- table's Hit / Target answer the target; the game's own writes go
        -- to a shadow and are put back the moment the casting is over (the
        -- same 3 s rule). The table's own metatable, pure Lua: no game call
        -- goes through it - only reads of that one table's Hit / Target.
        -- (The public hubs swap the remote's argument with a session-long
        -- __namecall hook instead - the one that broke this game's scripts.)
        local modT, modMt, modOld, shadow = nil, nil, nil, nil
        local function gameMouse()
            if modT then return modT end
            local ok, m = pcall(function()
                local ms = RS:FindFirstChild("Mouse")
                return ms and require(ms)
            end)
            if ok and type(m) == "table" then modT = m end
            return modT
        end
        local function modOn()
            if modOld then return end
            local m = gameMouse()
            if not m then return end
            local mt = getmetatable(m)
            if type(mt) ~= "table" then
                mt = {}
                if not pcall(setmetatable, m, mt) then return end
            end
            modMt, shadow = mt, { Hit = rawget(m, "Hit"), Target = rawget(m, "Target"), writes = 0 }
            modOld = { index = rawget(mt, "__index"), newindex = rawget(mt, "__newindex") }
            local oldIdx = modOld.index
            mt.__newindex = function(t, k, v)
                if k == "Hit" or k == "Target" then
                    shadow[k] = v
                    if k == "Hit" then shadow.writes += 1 end
                    return
                end
                rawset(t, k, v)
            end
            mt.__index = function(t, k)
                if k == "Hit" or k == "Target" then
                    local tgt = aimNow("skill")
                    if tgt then
                        if k == "Target" then
                            local part = P.aimPart
                            if part and part.Parent then return part end
                            return shadow.Target
                        end
                        local cam = workspace.CurrentCamera
                        local o = cam and cam.CFrame.Position or tgt
                        local d = tgt - o
                        return (d.Magnitude > 0.01) and CFrame.lookAt(tgt, tgt + d.Unit) or CFrame.new(tgt)
                    end
                    return shadow[k]
                end
                if type(oldIdx) == "function" then return oldIdx(t, k) end
                if type(oldIdx) == "table" then return oldIdx[k] end
                return nil
            end
            rawset(m, "Hit", nil)
            rawset(m, "Target", nil)
            P.gameAimSeen = P.gameAimSeen or 0
        end
        local function modOff()
            if not modOld then return end
            modMt.__index, modMt.__newindex = modOld.index, modOld.newindex
            modOld = nil
            P.gameAimSeen = (P.gameAimSeen or 0) + shadow.writes
            rawset(modT, "Hit", shadow.Hit or CFrame.new())
            rawset(modT, "Target", shadow.Target)
        end
        P.gameAimHooked = function() return modOld ~= nil end
        -- What the panel says: in / ready, and whether the game was seen
        -- writing to that table (= it IS the game's own, not a copy).
        function P.gameAimText()
            if not gameMouse() then return "the game's skill aim (ReplicatedStorage.Mouse) not found" end
            local seen = (P.gameAimSeen or 0) + (modOld and shadow.writes or 0)
            return (modOld and "in (casting)" or "ready")
                .. ((seen > 0) and "  ·  the game's own table (it aims it, seen)"
                    or (P.gameAimSeen and "  ·  the game never wrote it while hooked - not its table?" or ""))
        end

        local function hookOff()
            if not oldIndex then return end
            local o = oldIndex
            oldIndex = nil
            pcall(hookmetamethod, game, "__index", o)
            _G.BFF_SILENT_OFF = nil
            if not (_G.BFF_SILENT_HOOKED and P.silentNote and string.find(P.silentNote, "REJOIN", 1, true)) then
                P.silentNote = "ready (hooks only while casting)"
            end
        end
        function P.silentOff()
            modOff()
            hookOff()
        end

        local function silentOn()
            if oldIndex or not canHook() then return end
            -- A copy that was replaced without its stop: its hook out first.
            if _G.BFF_SILENT_OFF then pcall(_G.BFF_SILENT_OFF) end
            local cc = checkcaller or function() return false end
            local wrap = newcclosure or function(f) return f end
            local mouse = player:GetMouse()
            local mine
            mine = wrap(function(self, key)
                -- The script's own reads see your real mouse - except while it
                -- runs the game's own gun shot (P.inGameShot, THE GUN): that is
                -- the game reading it, on this script's thread.
                if (key == "Hit" or key == "Target" or key == "UnitRay" or key == "X" or key == "Y")
                    and rawequal(self, mouse) and (P.inGameShot or not cc()) then
                    local t = aimNow("gun")
                    if t then
                        local cam = workspace.CurrentCamera
                        local o = cam and cam.CFrame.Position or t
                        local d = t - o
                        if key == "Hit" then
                            return (d.Magnitude > 0.01) and CFrame.lookAt(t, t + d.Unit) or CFrame.new(t)
                        elseif key == "UnitRay" then
                            return Ray.new(o, (d.Magnitude > 0.01) and d.Unit or Vector3.new(0, -1, 0))
                        elseif key == "Target" then
                            local part = P.aimPart
                            if part and part.Parent then return part end
                        elseif cam then
                            local sp = cam:WorldToScreenPoint(t)
                            return (key == "X") and sp.X or sp.Y
                        end
                    end
                end
                return oldIndex(self, key)
            end)
            local ok, old = pcall(hookmetamethod, game, "__index", mine)
            if ok and old then
                oldIndex = old
                _G.BFF_SILENT_OFF = P.silentOff
                if not string.find(tostring(P.silentNote), "REJOIN", 1, true) then
                    P.silentNote = "in (casting)"
                end
            else
                P.silentNote = "the hook failed - the camera aim only"
            end
        end

        -- Every frame: want = the script is firing at a point right now.
        function P.silentTick(want, now)
            now = now or os.clock()
            if want and CFG.SilentAim and P.running then
                lastWant = now
                silentOn()
                modOn()
            elseif (oldIndex or modOld) and (now - lastWant > IDLE_OFF or not CFG.SilentAim or not P.running) then
                P.silentOff()
            end
        end

        -- PvP (2026-10-11): YOUR casts, aimed. The game's skill-aim table is
        -- taken over while a player is picked - its own metatable, pure Lua,
        -- no game call goes through it, so it may stay in for the fight. The
        -- mouse hook (__index) goes in ONLY while a gun is in your hand (only
        -- the gun reads your mouse) and out 3 s after - the window rule above.
        local lastModWant, lastHookWant = 0, 0
        function P.pvpAimTick(wantMod, wantHook, now)
            now = now or os.clock()
            if wantMod then
                lastModWant = now
                modOn()
            elseif modOld and now - lastModWant > IDLE_OFF then
                modOff()
            end
            if wantHook then
                lastHookWant = now
                silentOn()
            elseif oldIndex and now - lastHookWant > IDLE_OFF then
                hookOff()
            end
        end
    end
    build()
end
-- (end of silent aim)

-- =========================================================
-- PVP
-- =========================================================
-- User, 2026-10-11 (voice): one PvP switch. You fight with your own hands;
-- the script helps. Read in the game's own client (decompiled v4623):
--
-- THE KEN VIEW is drawn by your client only: require(RS.Global).OM, an
-- ObservationManager - outlines and HP bars out to your VisionRadius, and
-- the screen look (yours is Observation V2: the clean one). The game turns
-- it OFF through that object: DisableKen (out of dodges) ->
-- OM:setActive(false) and radius 0, and the character's Observation loop
-- turns it off again every 0.3 s while KenDisabled (the cooldown) is on
-- you. So while PvP is on that object's OFF is dropped (an instance field
-- over the class method - no hook) and its radius is kept full. It IS the
-- game's own view, never a copy (user: "don't make a new vision, just keep
-- it on"). Only when that object cannot be reached does a second copy of
-- the same class stand in. In PvP your E therefore always asks for Ken ON.
--
-- KEN ITSELF (the dodges) is the server's: player attributes KenActive /
-- KenDodgesLeft. Off -> 2 s, then every 0.5 s: CommE("Ken", true), the call
-- E sends, as soon as KenDisabled is gone.
--
-- CLEAN SCREEN: a Ghoul V4 near you adds a red, grey ColorCorrection to
-- Lighting and a "Dark/Gradient" screen to your PlayerGui; an Angel V4 a
-- grey ColorCorrection and camera shake. Every screen effect that was not
-- there when PvP went on is switched off, Dark/Gradient too, and the camera
-- shaker's ShakeOnce / Shake do nothing.
--
-- AIM: skills and a fruit's M1 read require(RS.Mouse).Hit -> SILENT AIM's
-- table override, in while a player is picked; a gun reads your mouse ->
-- the __index hook, only with a gun in your hand. A melee / sword M1 has no
-- aim at all: a box ~8 studs in front of your body (CombatUtil
-- RunHitDetection), and for every other move the game turns your body to
-- your MOUSE. So (user, 2026-10-12, build .8) the player is the one nearest
-- your MOUSE on the screen (within PvpCatchPx of the cursor - the aim
-- assist), picked again every frame and highlighted red, and for every
-- attack (any weapon, the fox form) your body is turned to him. (Build .7
-- took the nearest to YOU and locked him: in a crowd your mouse was on one
-- and the hits went to the one behind you.)
--
-- WHERE HE WILL BE (user, 2026-10-13: "if he is really fast, because of the
-- animation of my attack it misses - predict his movement"). Read in the
-- client: a skill sends your aim at the press, a frame later and at the
-- release (new-style moves every frame), and the SERVER runs the move - it
-- lands where he is on the server, which is your ping + the screen's buffer
-- AHEAD of what you see, plus the move's travel. So skills, a fruit's M1 and
-- a slow gun's shot (Cannon, Bazooka) go where he will be then: his path
-- read every frame (run kept, a dash dying out, a jump falling, a flight
-- straight, the floor under him), your ping measured. A ray gun (every
-- other gun) is cast by YOUR client at what you see - aimed at him, never
-- ahead; a melee / sword swing is a box on your client - faced at him as
-- he is. While a move plays your aim is sent again every frame (old-style
-- moves sent it only at the press), and the game's own gun snap to his
-- head (no lead) is off.
--
-- SPEED: the game writes WalkSpeed itself every frame, 36 x (race +
-- bonuses), and the character attribute SpeedMultiplier (Pilot Helmet 1.3)
-- is one of the bonuses. So that attribute is set so the game's OWN number
-- comes out at PvpSpeedTo - never WalkSpeed (a fight: it rewrites it).
-- Carried through V4 and every transformation (user, 2026-10-23): a form
-- counts the attribute at its own rate (Kitsune a quarter), so it is set
-- in that form's units, and a server write over it (V4 going on) is
-- answered at once.
-- DASH: the game moves every dash 0.3 s at its dash speed + the character
-- attribute DashLength, so that attribute is set for x PvpDashX the speed
-- (and so the distance) - worked out, never measured (a measured dash was
-- told apart from your run by speed, and a boosted run hid it). Its
-- animation is only a look: played PvpDashAnim x the game's speed. LEGS:
-- the run animation held at the pace of a 50 studs/s run, however fast.
do
    local function build()
        local UIS      = game:GetService("UserInputService")
        local Lighting = game:GetService("Lighting")
        local CS       = game:GetService("CollectionService")

        -- PVP LOGIC (pure: tools/pvp_test.py runs these on their own)
        local L = {}

        -- Can he be hit: alive, his PvP on, not on your side (two Marines
        -- cannot hurt each other; pirates can).
        function L.attackable(alive, pvpOff, myTeam, hisTeam)
            if not alive or pvpOff then return false end
            if myTeam == "Marines" and hisTeam == "Marines" then return false end
            return true
        end

        -- WHO (user, 2026-10-12, build .8: "whoever my mouse is aiming at gets
        -- the highlight and takes the attack"). The player nearest your CURSOR
        -- on the screen, within radius pixels of it - the cursor need not be ON
        -- him (the aim assist); two near it: the one nearer the cursor, not the
        -- one nearer you. Only one that can be hit, in front of the camera,
        -- within range studs. cands = { {id, dist, ok, sx, sy, front} }, mx / my
        -- = the cursor (the same pixels). Nobody that near = nil: your attack
        -- goes where your mouse points. cur (2026-10-13) = the id picked last
        -- frame: his catch area is 1.5x (the game's own aim assist does the
        -- same) and another takes over only when clearly nearer the cursor
        -- (0.8x) - a fast player no longer drops out of the pick for a frame.
        function L.cursorPick(cands, mx, my, radius, range, cur)
            local best, bestD, keep, keepD = nil, nil, nil, nil
            for _, c in ipairs(cands) do
                if c.ok and c.front and c.sx and c.sy and c.dist <= range then
                    local d = math.sqrt((c.sx - mx) ^ 2 + (c.sy - my) ^ 2)
                    if cur ~= nil and c.id == cur and d <= radius * 1.5 then keep, keepD = c, d end
                    if d <= radius and (bestD == nil or d < bestD) then best, bestD = c, d end
                end
            end
            if keep and (best == nil or best == keep or bestD > keepD * 0.8) then return keep end
            return best
        end
        -- FACING (user, 2026-10-12: every attack, any weapon, "the character is
        -- the script's job"): turned to him while an attack key / M1 is held,
        -- while the move plays (the game busy, within 3 s of an attack press),
        -- and 0.4 s after - only while he is within range. -> face until.
        function L.faceUntil(untilNow, now, held, busy, lastAttack, dist, range, on)
            if not on or dist == nil or dist > range then return untilNow end
            if held or (busy and now - (lastAttack or -1e9) < 3) then
                return math.max(untilNow, now + 0.4)
            end
            return untilNow
        end
        -- PER ATTACK (user, 2026-10-14: "I don't want aim assist on the Z
        -- move"). Is the aim on for what you fire now? on = { M1 = bool, Z =
        -- ... } (missing = on), down = the attack keys held this instant (the
        -- game reads your aim in the press's own frame, whether or not this
        -- script has heard the press yet), last = your last attack key and
        -- playing = its move still plays (the aim is read again at release).
        -- Any of them switched off = your own mouse.
        -- onLast (2026-10-14: per weapon) = the switches of the weapon the last
        -- attack was made with (nil = the same as on): a sword Z still playing
        -- stays yours after you swap to the fruit.
        function L.aimFor(on, down, last, playing, onLast)
            for k in pairs(down) do
                if on[k] == false then return false end
            end
            if last ~= nil and playing and (onLast or on)[last] == false then return false end
            return true
        end
        -- One weapon's switches: keys[kind] ("Blox Fruit", "Melee", "Sword",
        -- "Gun" - the tool's own label). Not listed = {} = every attack aimed.
        function L.aimOn(keys, kind)
            local t = type(keys) == "table" and kind ~= nil and keys[kind] or nil
            return type(t) == "table" and t or {}
        end

        -- WHERE HE WILL BE (user, 2026-10-13). h = his last places, oldest
        -- first: { {t, x, y, z}, ... }, 0.5 s kept. A step faster than 600
        -- studs/s (and over 8 studs) is a blink - Soru, a script's teleport
        -- dash, a respawn; also one your screen smooths over 2-3 frames - and
        -- his old path tells nothing: forgotten.
        function L.track(h, now, x, y, z)
            local last = h[#h]
            if last then
                if now <= last[1] then return end
                local dx, dy, dz = x - last[2], y - last[3], z - last[4]
                local d2 = dx * dx + dy * dy + dz * dz
                local lim = 600 * (now - last[1])
                if d2 > 64 and d2 > lim * lim then table.clear(h) end
            end
            table.insert(h, { now, x, y, z })
            while #h > 2 and now - h[1][1] > 0.5 do table.remove(h, 1) end
        end
        -- The newest look at or before time t (the oldest, if none is).
        local function sampleAt(h, t)
            local best = h[1]
            for i = 2, #h do
                if h[i][1] <= t then best = h[i] else break end
            end
            return best
        end
        -- His velocity (studs/s) from time t0 to t1, and the middle of that
        -- span; nil when the looks there cover under 0.03 s.
        function L.velBetween(h, t0, t1)
            if #h < 2 then return nil end
            local a, b = sampleAt(h, t0), sampleAt(h, t1)
            local dt = b[1] - a[1]
            if dt < 0.03 then return nil end
            return (b[2] - a[2]) / dt, (b[3] - a[3]) / dt, (b[4] - a[4]) / dt, (a[1] + b[1]) / 2
        end
        -- His motion now: the velocity of the last 0.1 s, and his up / down
        -- pull (that velocity against the 0.1 s before it). nil = unknown.
        function L.motion(h, now)
            local vx, vy, vz, m1 = L.velBetween(h, now - 0.1, now)
            if not vx then return nil end
            local ay = 0
            local _, vy0, _, m0 = L.velBetween(h, now - 0.2, now - 0.1)
            if vy0 and m1 - m0 > 0.04 then ay = (vy - vy0) / (m1 - m0) end
            return vx, vy, vz, ay
        end
        -- How long (s, in 0.1 steps, up to 0.4) he has gone faster than cap
        -- flat: a dash is over by then, a flight / a boat / Agility is not.
        function L.fastFor(h, now, cap)
            local t = 0
            for k = 0, 3 do
                local vx, _, vz = L.velBetween(h, now - (k + 1) * 0.1, now - k * 0.1)
                if not vx or vx * vx + vz * vz <= cap * cap then break end
                t = (k + 1) * 0.1
            end
            return t
        end
        -- How far ahead (s) to aim for this attack. "hitscan" = a ray YOUR
        -- client casts at what you see: none. Anything the server runs (a
        -- skill, a fruit's M1, a slow gun's shot) lands where he is ON THE
        -- SERVER: your ping there and back + the screen's buffer (0.05)
        -- ahead of what you see, + the travel (dist / speed). x scale, <= 1 s.
        function L.leadTime(kind, rtt, dist, speed, scale)
            if kind == "hitscan" then return 0 end
            local t = (rtt or 0.15) + 0.05 + dist / math.max(speed or 300, 50)
            return math.clamp(t * (scale or 1), 0, 1)
        end

        -- THE LEAD LEARNS (user, 2026-10-24). One lead never fits every move:
        -- on 2026-10-14 a lead on every move gave no hits, none at all lands
        -- the Buddy Sword's X and misses its Z ~70 %. So each MOVE (the
        -- weapon's name + its key) tries these amounts of lead (x the lead
        -- time) and keeps the one that hits him most. arms[i] = { n = tries,
        -- h = hits } for L.ARMS[i].
        L.ARMS = { 0, 0.25, 0.5, 0.75, 1 }
        -- Which amount now: how often it hit (no lead starts ahead - it is what
        -- lands today) plus a doubt bonus that shrinks the more an amount is
        -- tried, so a move that keeps missing tries the others (UCB). Ties go
        -- to less lead.
        function L.armPick(arms)
            local total = 0
            for i = 1, #L.ARMS do total += (arms[i] and arms[i].n or 0) end
            local best, bestScore = 1, -math.huge
            for i = 1, #L.ARMS do
                local a = arms[i]
                local n, h = a and a.n or 0, a and a.h or 0
                local mean = (h + ((i == 1) and 1.5 or 1)) / (n + 2)
                local score = mean + 0.3 * math.sqrt(math.log(total + 1) / (n + 1))
                if score > bestScore + 1e-9 then best, bestScore = i, score end
            end
            return best
        end
        -- One try into its amount; old tries fade (past 40 the counts halve:
        -- opponents and patches change).
        function L.armAdd(arms, i, hit)
            local a = arms[i]
            if not a then
                a = { n = 0, h = 0 }
                arms[i] = a
            end
            a.n += 1
            if hit then a.h += 1 end
            if a.n > 40 then a.n, a.h = a.n / 2, a.h / 2 end
        end
        -- HIT OR MISS. A try = { who, t0, hit, dmg, ... }, oldest first. Something
        -- on him - his HP down (dmg = the share of his max), or one of his Ken
        -- dodges used (dmg 0: your move reached him, his Ken took it) - goes to
        -- the oldest open try on him not yet credited; all credited = the
        -- newest's damage (a move hitting again). -> the try, or nil.
        function L.credit(tries, who, now, dmg)
            local newest
            for _, t in ipairs(tries) do
                if t.who == who and now >= t.t0 + 0.03 then
                    if not t.hit then
                        t.hit = true
                        t.dmg += dmg
                        return t
                    end
                    newest = t
                end
            end
            if newest then newest.dmg += dmg end
            return newest
        end
        -- A try is over 1.5 s after the press - later while its move still
        -- plays (a held move) - and never past 5 s.
        function L.tryDone(t, now, playing)
            if now - t.t0 >= 5 then return true end
            if now - t.t0 < 1.5 then return false end
            return not playing
        end
        -- How far he goes flat in t s. A run keeps going; speed past cap (a
        -- dash) dies out in ~tau s unless it has lasted (sustained). A burst
        -- past 400 studs/s that has not lasted is a blink in progress: it
        -- stops somewhere close - at most 15 studs on. <= 150.
        function L.aheadXZ(vx, vz, t, cap, sustained, tau)
            local s = math.sqrt(vx * vx + vz * vz)
            if s < 2 or t <= 0 then return 0, 0 end
            local d = s * t
            if not sustained and s > 400 then
                d = math.min(d, 15)
            elseif not sustained and s > cap then
                d = cap * t + (s - cap) * tau * (1 - math.exp(-t / tau))
            end
            d = math.min(d, 150)
            return vx / s * d, vz / s * d
        end
        -- His root's height in t s. g = the game's gravity, h0 = his root
        -- over the floor under him now, floorThen = the floor where he will
        -- be (nil = none seen). On the ground: the same height over that
        -- floor (slopes, steps). In the air: gravity (falling, or just
        -- jumped / air-jumped), unless his measured pull is ~0 (flying) -
        -- and never under the floor.
        function L.aheadY(y, vy, ay, t, g, h0, floorThen)
            if t <= 0 then return y end
            if h0 ~= nil and h0 < 4.5 and math.abs(vy) < 8 then
                return floorThen and (floorThen + h0) or y
            end
            local a = (math.abs(ay) < 0.3 * g) and 0 or -g
            local yy = y + vy * t + 0.5 * a * t * t
            if floorThen then yy = math.max(yy, floorThen + 3) end
            return math.clamp(yy, y - 80, y + 80)
        end

        -- The speed one unit of the attribute is worth in the form you are in
        -- (the game's Movement script, decompiled v4623): none / V4 / any
        -- other form 36 x (race + bonuses + attr - 1) -> 36; Kitsune
        -- (bonuses x 0.25 + 1) x 36 -> 9; Tiger (x 0.5 + 1) x 40 -> 20; the
        -- West Dragon (x 0.0135 + 1) x 64 -> 0.864; Mammoth (bonuses / 4) and
        -- Buddha (x 0.25) -> 9. f = the rigs on you: { Kitsune = true, ... }.
        function L.slope(f)
            if f.Kitsune then return 9 end
            if f.TigerRig then return 20 end
            if f.WesternDragonRig then return 64 * 0.0135 end
            if f.Mammoth or f.Buddha then return 9 end
            return 36
        end

        -- SPEED. s = { base = the server's SpeedMultiplier (nil = none), mine
        -- = the last value written here, add = the speed it adds (from the
        -- last clean look), k = the form then }. attr = the attribute now,
        -- ws = the game's WalkSpeed now, clean = that number can be read (not
        -- busy, swimming, walking, nor right after a write), k = L.slope of
        -- your form now. Returns the value to write, or nil = leave it. In
        -- every form the game's number is straight in the attribute, so the
        -- game's own number without this = ws - k x (attr - base).
        -- CARRY (user, 2026-10-23: "any transformation should carry the
        -- speed"): the server writing over ours (V4 writes 1.1 the moment it
        -- goes on; gear; a new life) or a new form = the speed added before,
        -- written again AT ONCE in the new form's units - a fight keeps you
        -- Busy, so a clean look can be seconds away; that look then trims it
        -- to the goal.
        function L.speed(s, attr, ws, target, clean, k)
            local wiped = attr ~= s.mine
            if wiped then s.base = attr end              -- the server set it (gear, V4, a new life)
            local newForm = s.k ~= nil and k ~= s.k
            s.k = k
            local b = s.base or 1
            local cur = attr or 1
            if clean and not newForm then
                local own = ws - k * (cur - b)           -- the game's number without this
                s.add = math.max(0, target - own)
            elseif not ((wiped or newForm) and s.add) then
                return nil
            end
            local want = b + math.min(s.add, 500) / k    -- at most +500 speed
            if math.abs(want - cur) < 0.005 then return nil end
            s.mine = want
            return want
        end

        -- FAR VISION (user, 2026-10-23). The game's Observation loop grows its
        -- view to player.VisionRadius every 0.3 s and never past it; the
        -- server writes that value (your Observation level - the hubs' auto
        -- Ken stops at 3,000 - x your accessories' ObservationRange: Pale
        -- Scarf 10) and nothing else reads it. v = { base = the server's
        -- value, mine = the last value written here }, cur = the value now.
        -- -> the value to write (never under the server's own), or nil.
        function L.far(v, cur, goal)
            if cur ~= v.mine then v.base = cur end       -- the server set it (gear, a level)
            local want = math.max(v.base or 0, goal)
            if cur == want then return nil end
            v.mine = want
            return want
        end

        -- DASH (the game's Dodge script, read 2026-10-23): every dash moves
        -- you for 0.3 s at a speed easing off from its top; the top = this
        -- base + the character attribute DashLength (race / gear add 5-10).
        -- The time is fixed, so the distance follows the speed. race = Data.
        -- Race.Value, night = ClockTime past 18 or before 6, has = what is on
        -- you: { Agility, ["Heightened Senses"] (root children), Kitsune,
        -- LeopardRig, LeopardBoost, KitsuneTail3, Mammoth } = true.
        function L.dashBase(race, evolved, night, has)
            local s
            if race == "Mink" and evolved then
                s = has.Agility and 120 or 112.5
                if has.Kitsune then s -= 7.5 end
            elseif race == "Ghoul" and evolved and night then
                s = 107.5
                if has.Kitsune then s -= 5 end
            else
                s = 92.5
            end
            if has["Heightened Senses"] then s = has.Kitsune and 112.5 or 117.5 end
            if has.LeopardRig then s += 10 end
            if has.LeopardBoost then s += 25 end
            if has.KitsuneTail3 then s = math.min(s + 15, math.max(s, 120)) end
            if has.Mammoth then s = 132 end             -- (Mammoth: DashLength not counted)
            return s
        end
        -- d = { base = the server's DashLength (nil = none), mine = the last
        -- value written here }. x = how many times as fast (and as far), s0 =
        -- L.dashBase. -> the attribute to hold: exact, nothing measured.
        function L.dashWant(d, attr, x, s0)
            if attr ~= d.mine then d.base = attr end    -- the server set it (gear, a new life)
            if x <= 1 then return d.base end
            local b = d.base or 0
            return b + (x - 1) * (s0 + b)
        end

        -- ANIMATIONS. Which of yours a track is: "dash" (the game's Dash*
        -- tracks, played at 1.65 - 1.45 sideways), "legs" (Animate's run /
        -- walk family: run, runKitsune, walkHover, ...) or nil. a = the
        -- Animation's name, t = the track's.
        function L.animKind(a, t)
            a, t = tostring(a or ""), tostring(t or "")
            if a:lower():find("dash", 1, true) or t:lower():find("dash", 1, true) then return "dash" end
            if a:find("^run") or a:find("^walk") then return "legs" end
            return nil
        end
        -- LEGS (user, 2026-10-23: "my foot movement doesn't need to match my
        -- speed"). Animate sets the run track's speed by your speed / 26 every
        -- step. mine = the speed written here last (nil = none), cur = the
        -- track's speed now, p = how fast you go (studs/s), pace = the legs'
        -- most. -> the speed to give the track (as if you ran pace), or nil.
        function L.legs(mine, cur, p, pace)
            if mine ~= nil and math.abs(cur - mine) < 1e-3 then return nil end   -- ours still stands
            if p <= pace or cur <= 0 then return nil end
            return cur * pace / p
        end

        -- FLASH STEP'S CUT (2026-10-15). The game's cooldown = 15 s (10 for an
        -- evolved Human) x (1 - FlashstepCooldown); base = the server's own
        -- value (accessories; nil = none), cut = 0..95 %. Yours first, then
        -- the cut off what is left. -> the attribute to hold.
        function L.soruAttr(base, cut)
            base = base or 0
            if not cut or cut <= 0 then return base end
            return 1 - (1 - base) * (1 - math.clamp(cut, 0, 95) / 100)
        end

        -- KEN BACK. k = { offAt, nextAt, tries }. true = send the Ken call now.
        function L.kenStep(k, now, active, cooling, hasKen)
            if active then
                k.offAt, k.tries = nil, 0
                return false
            end
            if not hasKen then return false end
            if k.offAt == nil then
                k.offAt, k.nextAt = now, now + 2
                return false
            end
            if now < (k.nextAt or 0) then return false end
            if cooling then
                k.nextAt = now + 0.5
                return false
            end
            k.tries = (k.tries or 0) + 1
            -- The server not taking it 20 times in a row: slower, not forever.
            k.nextAt = now + ((k.tries > 20) and 3 or 0.5)
            return true
        end

        -- A screen effect that blinds: greyed, darkened, hard contrast, or a
        -- heavy blur that is not the game's own Blur.
        function L.blinding(kind, name, sat, bright, contrast, size)
            if kind == "ColorCorrectionEffect" then
                return (sat or 0) < -0.05 or (bright or 0) < -0.05 or (contrast or 0) > 0.25
            elseif kind == "BlurEffect" then
                return name ~= "Blur" and (size or 0) > 3
            end
            return false
        end
        -- (end of pvp logic)

        local S = {
            on = false, epoch = 0, L = L,
            target = nil,              -- { plr, char, root, dist }
            conns = {},
            view  = { note = "-", blocked = 0, ons = 0 },
            ken   = { note = "-", st = {}, sent = 0 },
            clean = { base = setmetatable({}, { __mode = "k" }), off = {}, count = 0 },
            shake = { saved = {}, done = false, note = "-" },
            speed = { note = "-", st = {} },
            far   = { note = "-", st = {} },
            dash  = { note = "-", st = {} },
            anim  = { animator = nil, mine = setmetatable({}, { __mode = "k" }), dashes = 0, probes = 0,
                note = "-", qAt = nil },
            soru  = { base = nil, mine = nil },
            cd    = { set = setmetatable({}, { __mode = "k" }), presses = 0, moves = 0, busy = false },
            faceUntil = 0, faced = 0, held = {}, lastAttack = -1e9,
            mark  = { hl = nil, bb = nil, char = nil },
            -- WHERE HE WILL BE (2026-10-13): each player's path, this frame's
            -- aim points (aimSkill = the skill table's, aimShot = your gun's),
            -- your ping, what your last attack was, who it went at.
            hist = setmetatable({}, { __mode = "k" }),
            aimSkill = nil, aimShot = nil, rtt = nil, pingAt = -1e9,
            lead = { t = 0, ahead = 0, speed = 0 },
            lastKind = "skill", castTarget = nil,
            stream = { last = 0, sent = 0 },
            -- the lead that learns per move (2026-10-24): what each move
            -- learned, the tries still open, the players they were at
            tune = { moves = {}, tries = {}, watch = {}, closed = 0, kens = 0 },
            snap = { mod = nil, orig = nil, at = 0 },
            -- a ray gun's spread held off (d = the game's entry), and your
            -- shots at him against his HP going down (did the server take them)
            spread = { d = nil, orig = nil, at = 0 },
            shots = { n = 0, drops = 0, last = nil, lastAt = -1e9, hp = nil, who = nil },
        }
        P.pvp = S
        local function hold(c) table.insert(S.conns, c) return c end

        local globalMod = nil
        local function G()
            if globalMod then return globalMod end
            local ok, g = pcall(function()
                local m = RS:FindFirstChild("Global")
                return m and require(m)
            end)
            if ok and type(g) == "table" then globalMod = g end
            return globalMod
        end
        local function visionRadius()
            local vr = player:FindFirstChild("VisionRadius")
            return vr and tonumber(vr.Value) or nil
        end

        -- ---------- THE KEN VIEW ----------
        local V = S.view
        V.om, V.orig, V.rawOld, V.own = nil, nil, nil, nil
        -- sync: back in step with the server (its Ken off = the view off, so
        -- E works as before). Not for a dead life's object: its OFF could
        -- reach the shared screen look the new life is using.
        local function unwrap(sync)
            local om = V.om
            if not om then return end
            V.om = nil
            pcall(rawset, om, "setActive", V.rawOld)
            if sync and V.orig and not player:GetAttribute("KenActive") then
                pcall(V.orig, om, false)
            end
            V.orig, V.rawOld = nil, nil
        end
        local function wrap(om)
            if V.om == om then return true end
            unwrap(false)
            local orig = om.setActive
            if type(orig) ~= "function" then return false end
            local rawOld = rawget(om, "setActive")
            local ok = pcall(rawset, om, "setActive", function(self, on, ...)
                -- OFF is dropped while PvP keeps the view - except for a life
                -- that is over (its object being taken down).
                local _, _, hum = parts()
                if on or not (S.on and CFG.PvpVision) or not hum or rawget(self, "_destroyed") then
                    return orig(self, on, ...)
                end
                V.blocked += 1
                return nil
            end)
            if not ok or rawget(om, "setActive") == rawOld then return false end
            V.om, V.orig, V.rawOld = om, orig, rawOld
            return true
        end

        local function viewTick(now)
            if not CFG.PvpVision then
                if V.om then unwrap(true) end
                if V.own then pcall(V.own.destroy, V.own) V.own = nil end
                V.note = "off"
                return
            end
            local char, root = parts()
            if not root then V.note = "waiting for your character" return end
            if V.char ~= char then V.char, V.charAt = char, now end
            local settled = now - (V.charAt or 0) > 1.5
            local r = visionRadius()
            local g = G()
            local om = g and g.OM
            if type(om) == "table" and not rawget(om, "_destroyed") then
                if V.own then pcall(V.own.destroy, V.own) V.own = nil end
                local held = wrap(om)
                if not settled then V.note = "a new life - on in a moment" return end
                if not om.active then
                    -- The game's own ON: its look, its outlines.
                    pcall(V.orig or om.setActive, om, true)
                    V.ons += 1
                end
                if r then pcall(function() if (om.radius or 0) < r then om.radius = r end end) end
                V.note = held and string.format("ON  ·  the game's own view  ·  %d offs kept off", V.blocked)
                    or "ON  ·  the game's view would not take the switch - turned back on when it goes off"
                return
            end
            -- The game's own object out of reach (this executor's require
            -- gave a copy of the Global module): a second view of the same
            -- class. Kept active; emptied (radius 0) while the game's own Ken
            -- view is on, so no enemy is outlined twice; its screen look put
            -- back when the game's turns off (both share one).
            if not settled then return end
            local gameOn = false
            pcall(function() gameOn = RS.Events.IsObservationActive:Invoke() == true end)
            if V.own and V.ownChar ~= char then pcall(V.own.destroy, V.own) V.own = nil end
            if not V.own then
                local ok, o = pcall(function() return require(RS.ObservationManager).new(player) end)
                if ok and type(o) == "table" then
                    V.own, V.ownChar, V.ownGame = o, char, gameOn
                    pcall(o.setActive, o, true)
                end
            end
            local o = V.own
            if not o then V.note = "the game's Ken view could not be reached" return end
            if V.ownGame and not gameOn then
                pcall(o.setActive, o, false)
                pcall(o.setActive, o, true)
            end
            V.ownGame = gameOn
            pcall(function()
                o.radius = gameOn and 0 or (r or 300)
                if now - (V.ownRef or 0) > 0.3 then V.ownRef = now o:refresh() end
            end)
            V.note = gameOn and "ON  ·  the game's own (Ken on)" or "ON  ·  a copy of the game's view (its own object out of reach)"
        end

        -- ---------- FAR VISION ----------
        local FV = S.far
        local function farRestore()
            local vr, st = player:FindFirstChild("VisionRadius"), FV.st
            if vr and st.mine ~= nil and st.base ~= nil and vr.Value == st.mine then
                pcall(function() vr.Value = st.base end)
            end
            FV.st = {}
        end
        -- Every frame: a server write (gear on / off, a new level) is
        -- answered before the game's next 0.3 s step can shrink the view.
        local function farTick()
            if not CFG.PvpFar then
                if FV.st.mine ~= nil then farRestore() end
                FV.note = "off - your gear's own reach"
                return
            end
            local vr = player:FindFirstChild("VisionRadius")
            if not vr then FV.note = "the game's VisionRadius not found" return end
            local want = L.far(FV.st, tonumber(vr.Value), CFG.PvpFarTo)
            if want then vr.Value = want end
            FV.note = string.format("%d studs  ·  your gear's own %s", math.floor(tonumber(vr.Value) or 0),
                FV.st.base and tostring(math.floor(FV.st.base)) or "?")
        end

        -- ---------- KEN ITSELF ----------
        local K = S.ken
        local function kenTick(now)
            local char, root = parts()
            local active = player:GetAttribute("KenActive") == true
            local cooling = char ~= nil and char:FindFirstChild("KenDisabled") ~= nil
            local hasKen = char ~= nil and CS:HasTag(char, "Ken")
            if CFG.PvpKenBack and root and L.kenStep(K.st, now, active, cooling, hasKen) then
                local rem = RS:FindFirstChild("Remotes")
                local ce = rem and rem:FindFirstChild("CommE")
                if ce then
                    pcall(function() ce:FireServer("Ken", true) end)
                    K.sent += 1
                end
            end
            local left, max = player:GetAttribute("KenDodgesLeft"), player:GetAttribute("KenMaxDodges")
            if active then
                K.note = string.format("ON  ·  %s / %s dodges", tostring(left or "?"), tostring(max or "?"))
            elseif not CFG.PvpKenBack then
                K.note = "OFF  ·  bringing it back is off"
            elseif not hasKen then
                K.note = "OFF  ·  this character has no Observation"
            elseif cooling then
                K.note = "OFF  ·  cooldown - back the moment it ends"
            else
                K.note = string.format("OFF  ·  asking again in %.1f s  (%d asked)",
                    math.max(0, (K.st.nextAt or now) - now), K.st.tries or 0)
            end
        end

        -- ---------- CLEAN SCREEN ----------
        local CL = S.clean
        local function eachEffect(fn)
            -- Not ipairs over the pair: no camera for a moment = a nil.
            local srcs = { Lighting, workspace.CurrentCamera }
            for i = 1, 2 do
                local src = srcs[i]
                if src then
                    for _, e in ipairs(src:GetChildren()) do
                        if e:IsA("PostEffect") then fn(e) end
                    end
                end
            end
        end
        local function cleanBaseline()
            for e in pairs(CL.base) do CL.base[e] = nil end
            eachEffect(function(e)
                local sat, br, ct, sz
                if e:IsA("ColorCorrectionEffect") then
                    sat, br, ct = e.Saturation, e.Brightness, e.Contrast
                elseif e:IsA("BlurEffect") then
                    sz = e.Size
                end
                if not L.blinding(e.ClassName, e.Name, sat, br, ct, sz) then CL.base[e] = true end
            end)
        end
        local function cleanTick()
            eachEffect(function(e)
                if not CL.base[e] and e.Enabled then
                    e.Enabled = false
                    if not CL.off[e] then CL.off[e] = true CL.count += 1 end
                end
            end)
            local pg = player:FindFirstChildOfClass("PlayerGui")
            for _, g in ipairs(pg and pg:GetChildren() or {}) do
                if string.sub(g.Name, 1, 13) == "Dark/Gradient" and g:IsA("LayerCollector") and g.Enabled then
                    g.Enabled = false
                    if not CL.off[g] then CL.off[g] = true CL.count += 1 end
                end
            end
        end
        local function cleanRestore()
            for e in pairs(CL.off) do
                if e.Parent then pcall(function() e.Enabled = true end) end
            end
            table.clear(CL.off)
        end

        -- ---------- NO CAMERA SHAKE ----------
        local SH = S.shake
        local DUMMY = setmetatable({}, { __index = function() return function() end end })
        local function shakeTables()
            local out = {}
            local u = RS:FindFirstChild("Util")
            if not u then return out end
            local cs = u:FindFirstChild("CameraShaker")
            if cs then
                local ok, m = pcall(require, cs)
                if ok and type(m) == "table" then table.insert(out, m) end
            end
            local ok, um = pcall(require, u)
            if ok and type(um) == "table" then
                local ok2, inst = pcall(function() return um.CameraShaker end)
                if ok2 and type(inst) == "table" then table.insert(out, inst) end
            end
            return out
        end
        local function shakeOff()
            if SH.done then return end
            SH.done = true
            local n = 0
            for _, t in ipairs(shakeTables()) do
                for _, m in ipairs({ "ShakeOnce", "Shake" }) do
                    if type(t[m]) == "function" then
                        local raw = rawget(t, m)
                        if pcall(rawset, t, m, function() return DUMMY end) then
                            table.insert(SH.saved, { t, m, raw })
                            n += 1
                        end
                    end
                end
            end
            SH.note = (n > 0) and ("off  ·  " .. n .. " shake calls stilled")
                or "the game's camera shaker not found (or locked) - shake stays"
        end
        local function shakeOn()
            for i = #SH.saved, 1, -1 do
                local s = SH.saved[i]
                pcall(rawset, s[1], s[2], s[3])
            end
            table.clear(SH.saved)
            SH.done = false
            SH.note = "on"
        end

        -- ---------- SPEED ----------
        local SP = S.speed
        local RIGS = { Kitsune = "Kitsune", TigerRig = "Tiger", WesternDragonRig = "Dragon", Mammoth = "Mammoth" }
        local function speedRestore()
            local char, st = player.Character, SP.st
            if char and st.mine ~= nil and char:GetAttribute("SpeedMultiplier") == st.mine then
                pcall(function() char:SetAttribute("SpeedMultiplier", st.base) end)
            end
            SP.st = {}
        end
        local function speedTick(now)
            if not CFG.PvpSpeed then
                if SP.st.mine ~= nil then speedRestore() end
                SP.note = "off"
                return
            end
            local char, root, hum = parts()
            if not hum then SP.note = "waiting for your character" return end
            if SP.char ~= char then SP.char, SP.charAt = char, now end
            local f, form = {}, nil
            for n, label in pairs(RIGS) do
                if char:FindFirstChild(n) then f[n], form = true, label end
            end
            if root and root:FindFirstChild("Buddha") then f.Buddha, form = true, form or "Buddha" end
            local busy = char:FindFirstChild("Busy")
            local g = G()
            local walking = g ~= nil and g.Running == false
            local clean = not (busy and busy.Value) and not walking and hum.WalkSpeed > 0 and not hum.Sit
                and hum:GetState() ~= Enum.HumanoidStateType.Swimming
                and now - (SP.wroteAt or 0) > 0.15 and now - (SP.charAt or 0) > 1
            local want = L.speed(SP.st, char:GetAttribute("SpeedMultiplier"), hum.WalkSpeed,
                CFG.PvpSpeedTo, clean, L.slope(f))
            if want then
                char:SetAttribute("SpeedMultiplier", want)
                SP.wroteAt = now
            end
            local v4 = char:FindFirstChild("RaceTransformed")
            SP.note = string.format("%.0f now  ·  goal %.0f%s%s", hum.WalkSpeed, CFG.PvpSpeedTo,
                form and ("  ·  " .. form .. " form") or "",
                (v4 and v4.Value and "  ·  V4" or "") .. (walking and "  ·  walking (Ctrl)" or ""))
        end

        -- ---------- DASH ----------
        local D = S.dash
        local AN = S.anim
        local function dashRestore()
            local char, st = player.Character, D.st
            if char and st.mine ~= nil and char:GetAttribute("DashLength") == st.mine then
                pcall(function() char:SetAttribute("DashLength", st.base) end)
            end
            st.mine = nil
        end
        local DASH_KIDS = { "Kitsune", "LeopardRig", "LeopardBoost", "KitsuneTail3", "Mammoth" }
        local DASH_ROOT = { "Agility", "Heightened Senses" }
        local function dashTick()
            if not CFG.PvpDash then
                if D.st.mine ~= nil then dashRestore() end
                D.note = "off"
                return
            end
            local char, root = parts()
            if not char then return end
            local data = player:FindFirstChild("Data")
            local race = data and data:FindFirstChild("Race")
            local has = {}
            for _, n in ipairs(DASH_KIDS) do
                if char:FindFirstChild(n) then has[n] = true end
            end
            for _, n in ipairs(DASH_ROOT) do
                if root and root:FindFirstChild(n) then has[n] = true end
            end
            local ct = Lighting.ClockTime
            local s0 = L.dashBase(race and race.Value, race ~= nil and race:FindFirstChild("Evolved") ~= nil,
                ct > 18 or ct < 6, has)
            local attr = char:GetAttribute("DashLength")
            local want = L.dashWant(D.st, attr, CFG.PvpDashX, s0)
            if want ~= attr then
                char:SetAttribute("DashLength", want)
                D.st.mine = want
            end
            D.note = string.format("top speed %.0f -> %.0f studs/s  ·  x%.1f  ·  0.3 s each",
                s0 + (D.st.base or 0), s0 + (want or 0), CFG.PvpDashX)
        end
        S.dashNote = function()
            local n = D.note
            if CFG.PvpDashAnim > 1 then n ..= string.format("\nanim   x%.1f  ·  %d dashes sped", CFG.PvpDashAnim, AN.dashes) end
            if CFG.PvpLegs then n ..= "\nlegs   " .. AN.note end
            return n
        end

        -- ---------- ANIMATIONS (user, 2026-10-23) ----------
        -- The dash's animation is only a look (the move is the 0.3 s above):
        -- each Dash track the game plays is sped PvpDashAnim x. The legs:
        -- Animate's run / walk tracks held at a 50 studs/s run's pace.
        local LEGS_PACE = 50
        local function animHook(animator)
            if AN.animator == animator then return end
            AN.animator = animator
            hold(animator.AnimationPlayed:Connect(function(track)
                if not S.on then return end
                local a = track.Animation
                local kind = L.animKind(a and a.Name, track.Name)
                -- what starts right after Q, in the console (the first 3 dashes)
                if os.clock() - (AN.qAt or -1e9) < 0.3 and AN.probes < 3 then
                    AN.probes += 1
                    print(string.format("[BFF] dash anim: %s / %s (%s)", tostring(a and a.Name), track.Name,
                        tostring(kind)))
                end
                if kind ~= "dash" or CFG.PvpDashAnim <= 1 then return end
                task.defer(function()
                    pcall(function() track:AdjustSpeed(track.Speed * CFG.PvpDashAnim) end)
                    AN.dashes += 1
                end)
            end))
        end
        local function animTick()
            local _, root, hum = parts()
            local animator = hum and hum:FindFirstChildOfClass("Animator")
            if not animator then return end
            animHook(animator)
            if not CFG.PvpLegs then AN.note = "off" return end
            local v = root.AssemblyLinearVelocity
            local p = math.sqrt(v.X * v.X + v.Z * v.Z)
            local n = 0
            for _, tr in ipairs(animator:GetPlayingAnimationTracks()) do
                local a = tr.Animation
                if L.animKind(a and a.Name, tr.Name) == "legs" then
                    local want = L.legs(AN.mine[tr], tr.Speed, p, LEGS_PACE)
                    if want then
                        tr:AdjustSpeed(want)
                        AN.mine[tr] = want
                    elseif AN.mine[tr] ~= nil and math.abs(tr.Speed - AN.mine[tr]) >= 1e-3 then
                        AN.mine[tr] = nil
                    end
                    if AN.mine[tr] ~= nil then n += 1 end
                end
            end
            AN.note = (n > 0) and string.format("held at a %d run  ·  you %d", LEGS_PACE, math.floor(p))
                or string.format("the game's own (under %d)", LEGS_PACE)
        end

        -- ---------- COOLDOWNS (user, 2026-10-15: chased down over 300-400 m -
        -- "they make their cooldowns shorter; I want mine 0 or half") ----------
        -- Read in the client (decompiled v4623), both TESTS, off by default:
        -- FLASH STEP (R, StarterCharacterScripts.Soru): YOUR client checks its
        --   cooldown - 15 s (10 for an evolved Human) x (1 - the character
        --   attribute FlashstepCooldown, accessories' cut) - and moves you
        --   itself (200 studs; 350 evolved Human), then tells the server. So
        --   that attribute is held at the server's own cut plus PvpSoruCut %
        --   (the server's value back when off). 10 energy a step, as ever.
        -- SKILLS (Z X C V F): your client keeps a ready flag, but the SERVER
        --   sends the cooldown (SetCooldown) and runs the move - it most likely
        --   refuses one sent early. The test: the tool's own IgnoreCooldowns
        --   (the game's admin switch) on the tool in your hand lets you press
        --   during the cooldown; the line counts your skill presses against the
        --   moves the game really started (Busy on you turning on).
        local SO = S.soru
        local function soruTick()
            local char = player.Character
            if not char then return end
            local attr = char:GetAttribute("FlashstepCooldown")
            if attr ~= SO.mine then SO.base = attr end          -- the server's own (gear, a new life)
            local cut = CFG.PvpSoruCut or 0
            local want = (cut > 0) and L.soruAttr(SO.base, cut) or SO.base
            if want ~= attr then
                char:SetAttribute("FlashstepCooldown", want)
                SO.mine = want
            end
        end
        local function soruRestore()
            local char = player.Character
            if char and SO.mine ~= nil and char:GetAttribute("FlashstepCooldown") == SO.mine then
                pcall(function() char:SetAttribute("FlashstepCooldown", SO.base) end)
            end
            SO.mine = nil
        end
        function S.soruNote()
            local race = player:FindFirstChild("Data") and player.Data:FindFirstChild("Race")
            local full = (race and race.Value == "Human" and race:FindFirstChild("Evolved")) and 10 or 15
            local char = player.Character
            local a = char and char:GetAttribute("FlashstepCooldown") or 0
            return string.format("Flash Step: %.1f s cooldown (the game's %d s)%s", full * (1 - a), full,
                ((CFG.PvpSoruCut or 0) > 0) and string.format("  ·  %d %% cut (test)", CFG.PvpSoruCut) or "")
        end

        local CD = S.cd
        local function cdOff()
            for t in pairs(CD.set) do
                pcall(function() if t:GetAttribute("IgnoreCooldowns") == true then t:SetAttribute("IgnoreCooldowns", nil) end end)
            end
            table.clear(CD.set)
        end
        local function cdTick()
            if not CFG.PvpCdTest then
                if next(CD.set) then cdOff() end
                return
            end
            local tool = heldTool()
            if tool and tool:FindFirstChild("Holding") and tool:GetAttribute("IgnoreCooldowns") ~= true then
                tool:SetAttribute("IgnoreCooldowns", true)
                CD.set[tool] = true
            end
            -- a move the game really started: Busy on you turning on
            local char = player.Character
            local b = char and char:FindFirstChild("Busy")
            local busy = b ~= nil and b.Value == true
            if busy and not CD.busy then CD.moves += 1 end
            CD.busy = busy
        end
        function S.cdNote()
            if not CFG.PvpCdTest then return "skills: the game's own cooldowns" end
            return string.format("skills off cooldown (test): %d presses  ·  %d moves the game started"
                .. "  (spam one key: far fewer moves = the server refuses it)", CD.presses, CD.moves)
        end

        -- ---------- AIM ----------
        -- Every player's path is read every frame (a new life = a new path),
        -- so the one your mouse moves to is predicted from his first frame.
        local function candidates(now)
            local _, root = parts()
            if not root then return {} end
            local out = {}
            local mine = player.Team and player.Team.Name or nil
            local cam = workspace.CurrentCamera
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= player then
                    local ch = p.Character
                    local r = ch and ch:FindFirstChild("HumanoidRootPart")
                    local h = ch and ch:FindFirstChildOfClass("Humanoid")
                    if r and h then
                        local pos = r.Position
                        local hs = S.hist[p]
                        if not hs or hs.root ~= r then hs = { root = r, h = {} } S.hist[p] = hs end
                        L.track(hs.h, now, pos.X, pos.Y, pos.Z)
                        -- Where he is on your screen: the same pixels as
                        -- GetMouseLocation (both count from the very top).
                        local sx, sy, front = nil, nil, false
                        if cam then
                            local sp = cam:WorldToViewportPoint(pos)
                            sx, sy, front = sp.X, sp.Y, sp.Z > 0
                        end
                        table.insert(out, {
                            id = p, plr = p, char = ch, root = r, hist = hs.h,
                            dist = (pos - root.Position).Magnitude,
                            ok = L.attackable(h.Health > 0, p:GetAttribute("PvpDisabled") == true,
                                mine, p.Team and p.Team.Name or nil),
                            sx = sx, sy = sy, front = front,
                        })
                    end
                end
            end
            return out
        end

        -- Your ping there and back (s): the game's own network stats, read
        -- twice a second, smoothed.
        local function pingNow(now)
            if S.rtt and now - S.pingAt < 0.5 then return S.rtt end
            S.pingAt = now
            local rtt = nil
            pcall(function()
                local ms = game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()
                if type(ms) == "number" and ms > 0 then rtt = ms / 1000 end
            end)
            if not rtt then pcall(function() rtt = player:GetNetworkPing() * 2 end) end
            rtt = math.clamp(tonumber(rtt) or 0.15, 0.02, 1)
            S.rtt = S.rtt and (S.rtt * 0.6 + rtt * 0.4) or rtt
            return S.rtt
        end

        -- The floor under a point: a ray down from just over it, through every
        -- character, enemy and effect.
        local rayP = RaycastParams.new()
        rayP.FilterType = Enum.RaycastFilterType.Exclude
        local rayAt = -1e9
        local function floorUnder(x, y, z, now)
            if now - rayAt > 1 then
                rayAt = now
                local ex = {}
                for _, n in ipairs({ "Characters", "Enemies", "_WorldOrigin" }) do
                    local f = workspace:FindFirstChild(n)
                    if f then table.insert(ex, f) end
                end
                if workspace.CurrentCamera then table.insert(ex, workspace.CurrentCamera) end
                if player.Character then table.insert(ex, player.Character) end
                rayP.FilterDescendantsInstances = ex
            end
            local r = workspace:Raycast(Vector3.new(x, y + 6, z), Vector3.new(0, -300, 0), rayP)
            return r and r.Position.Y or nil
        end

        -- Your gun's shot: "hitscan" (a ray your client casts) or "gun" (the
        -- server's projectile, at its own speed); nil = not a gun.
        local function shotKind(tool)
            local gi = tool and P.gunInfo and P.gunInfo(tool)
            if not gi then return nil, nil end
            if gi.projectile then return "gun", gi.speed or 200 end
            return "hitscan", nil
        end

        -- Your move playing: an attack within 3 s and the game busy with it
        -- (Busy on you, or the tool's Holding).
        local function movePlaying(now)
            if now - S.lastAttack > 3 then return false end
            local char = player.Character
            local busy = char and char:FindFirstChild("Busy")
            if busy and busy.Value == true then return true end
            local tool = heldTool()
            local hv = tool and tool:FindFirstChild("Holding")
            return hv ~= nil and hv.Value == true
        end

        -- Is the aim on for what you fire now (CFG.PvpAimKeys, L.aimFor)?
        local KEYCODES = { Z = Enum.KeyCode.Z, X = Enum.KeyCode.X, C = Enum.KeyCode.C,
            V = Enum.KeyCode.V, F = Enum.KeyCode.F }
        function S.aimAllowed(now)
            -- The weapon in your hand now (the fox: your fruit), and the one
            -- your last attack was made with.
            local on = L.aimOn(CFG.PvpAimKeys, toolType(heldTool()))
            local onLast = L.aimOn(CFG.PvpAimKeys, S.lastType)
            local down = {}
            for k, kc in pairs(KEYCODES) do
                if UIS:IsKeyDown(kc) then down[k] = true end
            end
            if UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then down.M1 = true end
            return L.aimFor(on, down, S.lastKey, movePlaying(now or os.clock()), onLast)
        end

        -- His motion this frame (read once, used by every aim point).
        local RUN_CAP, DASH_TAU = 140, 0.15
        local function motionOf(c, now)
            local pos = c.root.Position
            local vx, vy, vz, ay
            if c.hist then vx, vy, vz, ay = L.motion(c.hist, now) end
            if not vx then
                local v = c.root.AssemblyLinearVelocity
                vx, vy, vz, ay = v.X, v.Y, v.Z, 0
            end
            return {
                pos = pos, vx = vx, vy = vy, vz = vz, ay = ay,
                sustained = c.hist ~= nil and L.fastFor(c.hist, now, RUN_CAP) >= 0.4,
                floor = floorUnder(pos.X, pos.Y, pos.Z, now),
            }
        end
        -- Where he will be when this kind of hit lands, scale x the lead
        -- (0 / nil = where he is). -> point, lead (s).
        local function predict(mo, kind, dist, speed, now, scale)
            local p = mo.pos
            if not scale or scale <= 0 then return p, 0 end
            local t = L.leadTime(kind, pingNow(now), dist, speed, scale)
            local dx, dz = L.aheadXZ(mo.vx, mo.vz, t, RUN_CAP, mo.sustained, DASH_TAU)
            local fThen = mo.floor
            -- From over where he will be: up a hill the ground ahead is higher
            -- than he is now, and a ray started inside it sees no floor.
            if dx ~= 0 or dz ~= 0 then fThen = floorUnder(p.X + dx, math.max(p.Y, p.Y + mo.vy * t), p.Z + dz, now) end
            local y = L.aheadY(p.Y, mo.vy, mo.ay, t, workspace.Gravity,
                mo.floor and (p.Y - mo.floor) or nil, fThen)
            return Vector3.new(p.X + dx, y, p.Z + dz), t
        end

        -- ---------- THE LEAD LEARNS (user, 2026-10-24) ----------
        -- What each move learned, kept in workspace/bff_aim_learn.json:
        -- moves[id] = { arms = 5 x { n, h }, n, h, dmg } with id = "<weapon>|<key>".
        local TU = S.tune
        local TUNE_FILE = "bff_aim_learn.json"
        local HS = game:GetService("HttpService")
        pcall(function()
            if readfile and isfile and isfile(TUNE_FILE) then
                local d = HS:JSONDecode(readfile(TUNE_FILE))
                if type(d) == "table" and type(d.moves) == "table" then TU.moves = d.moves end
            end
        end)
        local function tuneSave()
            pcall(function()
                if writefile then writefile(TUNE_FILE, HS:JSONEncode({ v = 1, moves = TU.moves })) end
            end)
        end
        S.tuneSave = tuneSave
        local function tuneMove(id)
            local m = TU.moves[id]
            if type(m) ~= "table" then
                m = { arms = {}, n = 0, h = 0, dmg = 0 }
                for i = 1, #L.ARMS do m.arms[i] = { n = 0, h = 0 } end
                TU.moves[id] = m
            end
            return m
        end
        -- The move being made this instant: a key held now, else the last one
        -- while its move still plays (the aim is read again during it).
        local function moveNow()
            local tool = heldTool()
            if not tool then return nil end
            for _, k in ipairs({ "Z", "X", "C", "V", "F" }) do
                if UIS:IsKeyDown(KEYCODES[k]) then return tool.Name .. "|" .. k end
            end
            if UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then return tool.Name .. "|M1" end
            if S.lastKey and S.lastTool == tool.Name and movePlaying(os.clock()) then
                return tool.Name .. "|" .. S.lastKey
            end
            return nil
        end
        -- The lead (x) for a move: learned (PvpLeadAuto), else the old switch.
        -- Second value: the amount's index (nil = not learned).
        local function scaleFor(id)
            if not CFG.PvpLeadAuto then return (CFG.PvpLead and CFG.PvpLeadScale or 0), nil end
            if not id then return 0, nil end
            local m = TU.moves[id]
            local i = L.armPick(type(m) == "table" and m.arms or {})
            return L.ARMS[i], i
        end

        -- The pick (the one nearest your mouse) and this frame's aim points:
        -- aimSkill for the game's skill table, aimShot for your gun's shot.
        local function targetTick(now)
            local m = UIS:GetMouseLocation()
            local cands = candidates(now)
            local cur = S.target and S.target.id or nil
            local pick = L.cursorPick(cands, m.X, m.Y, CFG.PvpCatchPx, CFG.PvpRange, cur)
            -- A move playing keeps the one it was cast at (alive, in range)
            -- if your mouse slips off him in the chaos of it.
            if S.castTarget and movePlaying(now) then
                for _, c in ipairs(cands) do
                    if c.id == S.castTarget and c.ok and c.dist <= CFG.PvpRange then pick = c break end
                end
            end
            S.target = pick
            P.aimPart = pick and pick.root or nil
            S.aimSkill, S.aimShot = nil, nil
            if not pick then return end
            local mo = motionOf(pick, now)
            S.mo, S.moDist = mo, pick.dist
            local LD = S.lead
            LD.speed = math.sqrt(mo.vx * mo.vx + mo.vz * mo.vz)
            local sc = scaleFor(moveNow())
            S.aimScale = sc
            local t
            S.aimSkill, t = predict(mo, "skill", pick.dist, CFG.PvpSkillSpeed, now, sc)
            LD.t, LD.ahead = t, (S.aimSkill - mo.pos).Magnitude
            local kind, speed = shotKind(heldTool())
            LD.gun = kind
            if kind == "gun" then
                S.aimShot, LD.gunT = predict(mo, "gun", pick.dist, speed, now, sc)
            else
                S.aimShot, LD.gunT = mo.pos, 0       -- a ray gun: at him, as you see him
            end
        end
        -- What the aim sends: "gun" = your gun's shot, else the skill point.
        function S.aimPoint(kind)
            local t = S.target
            if not (t and t.root and t.root.Parent) then return nil end
            -- That attack's aim switched off: your own mouse.
            if not S.aimAllowed() then return nil end
            local a = (kind == "gun") and S.aimShot or S.aimSkill
            -- The game reads your aim IN the press: the move pressed this
            -- instant may want another lead than this frame's point had.
            local sc = scaleFor(moveNow())
            if S.mo and sc ~= S.aimScale then
                if kind == "gun" then
                    local k, sp = shotKind(heldTool())
                    if k == "gun" then a = predict(S.mo, "gun", S.moDist, sp, os.clock(), sc) end
                else
                    a = predict(S.mo, "skill", S.moDist, CFG.PvpSkillSpeed, os.clock(), sc)
                end
            end
            return a or t.root.Position
        end
        function S.targetText()
            if not CFG.PvpAim then return "aim off" end
            local t = S.target
            if not t then return "nobody near your mouse - your attacks go where it points" end
            -- His Ken dodges your hits whatever the aim: said, so a miss on him
            -- is not read as the aim's.
            local ken = ""
            if t.plr:GetAttribute("KenActive") == true then
                ken = string.format("  ·  HIS KEN ON (%s dodges left)", tostring(t.plr:GetAttribute("KenDodgesLeft") or "?"))
            end
            return string.format("%s  ·  %.0f studs  ·  your mouse is on him%s%s", t.plr.DisplayName or t.plr.Name, t.dist,
                (P.gameAimHooked and P.gameAimHooked()) and "  ·  aimed" or "", ken)
        end
        -- Which attacks the aim takes for the weapon in your hand, in words:
        -- "sword: aimed M1 X C V F · yours Z".
        local KIND_WORD = { ["Blox Fruit"] = "fruit", Melee = "fighting style", Sword = "sword", Gun = "gun" }
        function S.keysText()
            local kind = toolType(heldTool())
            local word = KIND_WORD[kind]
            if not word then return "no weapon in hand" end
            local on, a, y = L.aimOn(CFG.PvpAimKeys, kind), {}, {}
            for _, k in ipairs({ "M1", "Z", "X", "C", "V", "F" }) do
                table.insert((on[k] == false) and y or a, k)
            end
            return word .. ": aimed " .. ((#a > 0) and table.concat(a, " ") or "-")
                .. ((#y > 0) and ("  ·  yours " .. table.concat(y, " ")) or "")
        end
        function S.leadText()
            local LD = S.lead
            local s = S.keysText() .. "\n"
            local leading = CFG.PvpLeadAuto or CFG.PvpLead
            if not leading then
                s = s .. "lead off - aimed where he is"
            else
                s = s .. (CFG.PvpLeadAuto and string.format("lead learned per move (x%.2f now)", S.aimScale or 0)
                    or "lead on") .. string.format("  ·  ping %d ms", math.floor((S.rtt or 0) * 1000 + 0.5))
                if not S.target then return s .. "  ·  nobody picked" end
                s = s .. string.format("  ·  him %.0f studs/s  ·  skills %.2f s ahead = %.0f studs",
                    LD.speed or 0, LD.t or 0, LD.ahead or 0)
            end
            if LD.gun == "gun" and leading then
                s = s .. string.format("  ·  gun %.2f s ahead (its shot flies)", LD.gunT or 0)
            elseif LD.gun == "hitscan" then
                s = s .. "  ·  gun: a ray at him, no lead" .. (S.spread.d and ", straight (no spread)" or "")
            end
            s = s .. string.format("\nsent again while moves play: %d", S.stream.sent)
            if S.shots.n > 0 then
                s = s .. string.format("\ngun: %d shots at him  ·  his HP went down %d times while you shot",
                    S.shots.n, S.shots.drops)
            end
            return s
        end

        -- THE GAME'S OWN GUN SNAP (CombatController shootGun): a shot whose
        -- cursor is ~40 px from a head goes at that head AS IT IS - it would
        -- put the lead back to nothing. While your aim has a player and a gun
        -- is in your hand, its answer is "nobody" (the module's own field, the
        -- original back 3 s after and on PvP off).
        local SN = S.snap
        local function snapModule()
            if SN.mod == nil then
                local ok, m = pcall(function() return require(RS.Controllers.CombatController.AimAssist) end)
                SN.mod = (ok and type(m) == "table") and m or false
            end
            return SN.mod or nil
        end
        local function snapOff()
            if SN.orig then return end
            local m = snapModule()
            local orig = m and rawget(m, "getTargetInfo")
            if type(orig) ~= "function" then return end
            local mine = function(...)
                if S.on and CFG.PvpAim and S.target then return nil end
                return orig(...)
            end
            -- A module that will not take the write: not tried again.
            if pcall(rawset, m, "getTargetInfo", mine) then SN.orig = orig else SN.mod = false end
        end
        local function snapOn()
            if not SN.orig then return end
            pcall(rawset, SN.mod, "getTargetInfo", SN.orig)
            SN.orig = nil
        end

        -- A RAY GUN'S SPREAD (user, 2026-10-13: "Dragonstorm M1 should attack
        -- them properly"). Read in CombatController.shootGun: each shot is
        -- turned by up to BulletSpreadDegree / 2 each way (Dragonstorm 3 ->
        -- 1.5 deg; every 4th shot straight) before YOUR client casts the ray -
        -- at 100 studs up to 2.6 studs off, about a third miss his body, at 200
        -- most. The aim is already on him; the spread threw it off. While you
        -- aim a single-ray gun (HitscanSingleShot) at him, its spread is off in
        -- the game's own weapon table - the number put back 3 s after, on
        -- another gun, and on PvP off.
        local SPR = S.spread
        local function spreadOn()
            if not SPR.d then return end
            pcall(rawset, SPR.d, "BulletSpreadDegree", SPR.orig)
            SPR.d, SPR.orig = nil, nil
        end
        local function spreadOff(tool, now)
            local gi = tool and P.gunInfo and P.gunInfo(tool)
            local d = gi and gi.data
            if type(d) ~= "table" or d.ShootType ~= "HitscanSingleShot" then return end
            if SPR.d == d then SPR.at = now return end
            spreadOn()
            local deg = rawget(d, "BulletSpreadDegree")
            if type(deg) ~= "number" or deg <= 0 then return end
            if pcall(rawset, d, "BulletSpreadDegree", nil) then SPR.d, SPR.orig, SPR.at = d, deg, now end
        end

        -- YOUR SHOTS AT HIM against his HP going down: the gun's own shot count
        -- (LocalTotalShots) climbing while he is picked, and his health falling
        -- within 0.3 s of a shot. Many shots, few drops = the server is not
        -- taking them (a fast player's place on the server is ahead of yours).
        local SH_ = S.shots
        local function shotsTick(tool, now)
            local t = S.target
            local hum = t and t.char and t.char:FindFirstChildOfClass("Humanoid")
            local hp = hum and hum.Health or nil
            if SH_.who ~= (t and t.id) then SH_.who, SH_.hp = t and t.id, hp end
            local n = tool and tool:GetAttribute("LocalTotalShots")
            if SH_.tool ~= tool then SH_.tool, SH_.last = tool, nil end     -- another gun: its own count
            if type(n) == "number" then
                if t and SH_.last and n > SH_.last then
                    SH_.n += n - SH_.last
                    SH_.lastAt = now
                end
                SH_.last = n
            else
                SH_.last = nil
            end
            if hp and SH_.hp and hp < SH_.hp and now - SH_.lastAt < 0.3 then SH_.drops += 1 end
            SH_.hp = hp
        end

        -- ---------- YOUR AIM WHILE THE MOVE PLAYS ----------
        -- A skill sends your aim at the press, a frame later and at the
        -- release, and the server may hit with it well after (the windup).
        -- While your move plays it is sent again 20 times a second: the
        -- game's own payload to the tool's own remote, as its sendMouse does
        -- (a Vector3 to LegacyRemoteEvent / RemoteEvent, a CFrame to
        -- RemoteEvent; never Love's). New-style moves send it every frame
        -- themselves - this is the same value, again.
        local SR = S.stream
        local function streamTick(now)
            if not (CFG.PvpStream and CFG.PvpAim and S.target and S.aimSkill) then return end
            -- Only a move the server aims (a skill, a fruit's M1), not a swing or a shot.
            if S.lastKind ~= "skill" then return end
            if now - SR.last < 0.05 or not movePlaying(now) then return end
            if not S.aimAllowed(now) then return end
            local tool = heldTool()
            if not tool or tool.Name == "Love-Love" then return end
            local mp = tool:FindFirstChild("MousePos") or tool:FindFirstChild("Mouse")
            if not (mp and tool:FindFirstChild("Holding")) then return end
            local function remote(n)
                local r = tool:FindFirstChild(n)
                return (r and r:IsA("RemoteEvent")) and r or nil
            end
            local at = S.aimSkill
            SR.last = now
            if mp:IsA("Vector3Value") then
                local r = remote("LegacyRemoteEvent") or remote("RemoteEvent")
                if r then r:FireServer(at) SR.sent += 1 end
            else
                local r, cam = remote("RemoteEvent"), workspace.CurrentCamera
                if r and cam then
                    local d = at - cam.CFrame.Position
                    r:FireServer((d.Magnitude > 0.01) and CFrame.lookAt(at, at + d.Unit) or CFrame.new(at))
                    SR.sent += 1
                end
            end
        end

        -- Every attack, any weapon (user, 2026-10-12): a melee / sword swing is
        -- a box in front of your body, and for everything else the game turns
        -- your body to your MOUSE while the aim sends the move to him - so the
        -- body is turned to him whenever you attack him in range.
        local function faceWanted()
            local t = S.target
            return CFG.PvpFace and t ~= nil and t.dist <= CFG.PvpFaceRange
        end
        -- The attack keys (not Q / jump / moving): M1, Z X C V F.
        local ATTACK_KEYS = { [Enum.KeyCode.Z] = "Z", [Enum.KeyCode.X] = "X", [Enum.KeyCode.C] = "C",
            [Enum.KeyCode.V] = "V", [Enum.KeyCode.F] = "F" }
        -- Your attack: the body turned to the one your mouse is on. What it
        -- is (2026-10-13) decides where: a melee / sword swing ("melee") and a
        -- ray gun ("hitscan") hit what you SEE - him, as he is; a skill, a
        -- fruit's M1 (the fox's too) and a slow gun go where he will be.
        local function attackPressed(what)
            local now = os.clock()
            S.lastAttack = now
            S.held[what] = true
            S.lastKey = what
            if CFG.PvpCdTest and what ~= "M1" then S.cd.presses += 1 end
            local tool = heldTool()
            local tt = toolType(tool)
            S.lastType = tt
            if what ~= "M1" then S.lastKind = "skill"
            elseif tt == "Melee" or tt == "Sword" then S.lastKind = "melee"
            elseif tt == "Gun" then S.lastKind = (shotKind(tool) == "gun") and "gun" or "hitscan"
            else S.lastKind = "skill" end
            S.castTarget = S.target and S.target.id or nil
            S.lastTool = tool and tool.Name or nil
            -- An attack whose aim is off is not turned to him either: it is yours.
            local aimed = L.aimOn(CFG.PvpAimKeys, tt)[what] ~= false
            if faceWanted() and aimed then
                S.faceUntil = math.max(S.faceUntil, now + 0.4)
                S.faced += 1
            end
            -- A try at him: did it hit (his HP / his Ken dodges)? A move the
            -- server runs (a skill, a fruit's M1, a slow gun's shot) also says
            -- which lead it was made with; a swing / a ray gun hits what you see.
            local t = S.target
            if tool and t and t.plr and aimed and CFG.PvpAim then
                local id = tool.Name .. "|" .. what
                local _, arm = scaleFor(id)
                local leads = S.lastKind == "skill" or S.lastKind == "gun"
                table.insert(TU.tries, { id = id, who = t.plr, t0 = now, hit = false, dmg = 0,
                    arm = leads and arm or nil })
                while #TU.tries > 30 do table.remove(TU.tries, 1) end
                if not TU.watch[t.plr] then
                    local ch = t.plr.Character
                    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
                    TU.watch[t.plr] = { hp = hum and hum.Health, ken = t.plr:GetAttribute("KenDodgesLeft") }
                end
            end
        end

        -- Every frame: what happened to each player you tried a move at, and
        -- each try over its time counted into its move (and its lead).
        local function tuneTick(now)
            if #TU.tries == 0 then
                if next(TU.watch) then table.clear(TU.watch) end
                return
            end
            for plr, w in pairs(TU.watch) do
                local ch = plr.Character
                local hum = ch and ch:FindFirstChildOfClass("Humanoid")
                local hp = hum and hum.Health
                local ken = plr:GetAttribute("KenDodgesLeft")
                if hp and w.hp and hp < w.hp - 0.5 then
                    L.credit(TU.tries, plr, now, (w.hp - hp) / math.max(tonumber(hum.MaxHealth) or 100, 1))
                end
                if type(ken) == "number" and type(w.ken) == "number" and ken < w.ken then
                    L.credit(TU.tries, plr, now, 0)
                    TU.kens += 1
                end
                w.hp, w.ken = hp, ken
            end
            local keep, last = {}, TU.tries[#TU.tries]
            for _, t in ipairs(TU.tries) do
                if L.tryDone(t, now, t == last and movePlaying(now)) then
                    local m = tuneMove(t.id)
                    m.n += 1
                    if t.hit then
                        m.h += 1
                        m.dmg += t.dmg
                    end
                    if t.arm then L.armAdd(m.arms, t.arm, t.hit) end
                    TU.closed += 1
                    if TU.closed % 10 == 0 then tuneSave() end
                else
                    table.insert(keep, t)
                end
            end
            TU.tries = keep
            -- players no try is open on: no longer watched
            local open = {}
            for _, t in ipairs(keep) do open[t.who] = true end
            for plr in pairs(TU.watch) do
                if not open[plr] then TU.watch[plr] = nil end
            end
        end
        -- What each move learned, most tried first: "Buddy Sword Z · lead 0.50 · 7 of 12 hit (58 %)".
        function S.tuneText()
            local list = {}
            for id, m in pairs(TU.moves) do
                if type(m) == "table" and (m.n or 0) > 0 then table.insert(list, { id = id, m = m }) end
            end
            table.sort(list, function(a, b) return a.m.n > b.m.n end)
            local lines = {}
            for i, e in ipairs(list) do
                if i > 8 then break end
                local weapon, key = string.match(e.id, "^(.*)|(.-)$")
                local lead = CFG.PvpLeadAuto and string.format("lead %.2f", L.ARMS[L.armPick(e.m.arms or {})])
                    or "learning off"
                table.insert(lines, string.format("%s %s  ·  %s  ·  %d of %d hit (%d %%)%s",
                    tostring(weapon), tostring(key), lead, math.floor(e.m.h + 0.5), math.floor(e.m.n + 0.5),
                    math.floor(100 * e.m.h / math.max(e.m.n, 1) + 0.5),
                    (e.m.h > 0) and string.format("  ·  %d %% of his HP a hit", math.floor(100 * e.m.dmg / e.m.h + 0.5)) or ""))
            end
            if #lines == 0 then
                return "nothing tried yet - every move you aim at a player is counted: hit or not"
            end
            return table.concat(lines, "\n") .. string.format("\nhis Ken took %d of them (counted as reaching him)", TU.kens)
        end
        local function faceAt(t)
            if S.lastKind == "skill" and S.aimSkill then return S.aimSkill end
            if S.lastKind == "gun" and S.aimShot then return S.aimShot end
            return t.root.Position
        end
        local function faceNow()
            if os.clock() > S.faceUntil then return end
            local t = S.target
            local _, root = parts()
            if not (t and root and t.root.Parent) then return end
            if not S.aimAllowed() then return end
            local p, q = root.Position, faceAt(t)
            local flat = Vector3.new(q.X, p.Y, q.Z)
            if (flat - p).Magnitude < 1 then return end
            root.CFrame = CFrame.lookAt(p, flat)
        end

        -- ---------- THE MARK (user, 2026-10-12: "the player I'm attacking
        -- highlighted - even in a fiery, blasty animation I see him") ----------
        -- A Highlight drawn on top of everything (kept in your camera: made
        -- on your client, nobody else has it) + a red diamond over his head (a
        -- screen layer, always on top: a blast covering his whole body cannot
        -- hide where he is). Moved the frame your mouse picks another.
        local MK = S.mark
        local function markOff()
            if MK.hl then MK.hl.Enabled = false MK.hl.Adornee = nil end
            if MK.bb then MK.bb.Enabled = false MK.bb.Adornee = nil end
            MK.char = nil
        end
        local function markDestroy()
            if MK.hl then pcall(function() MK.hl:Destroy() end) end
            if MK.bb then pcall(function() MK.bb:Destroy() end) end
            MK.hl, MK.bb, MK.char = nil, nil, nil
        end
        local function markTick()
            local t = S.target
            local cam = workspace.CurrentCamera
            if not (CFG.PvpMark and t and t.char and t.char.Parent and cam) then markOff() return end
            if not (MK.hl and MK.hl.Parent) then
                local hl = Instance.new("Highlight")
                hl.Name = "BFFMark"
                hl.FillColor = Color3.fromRGB(255, 30, 30)
                hl.FillTransparency = 0.35
                hl.OutlineColor = Color3.new(1, 1, 1)
                hl.OutlineTransparency = 0
                hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                hl.Parent = cam
                MK.hl, MK.char = hl, nil
            end
            if not (MK.bb and MK.bb.Parent) then
                local bb = Instance.new("BillboardGui")
                bb.Name = "BFFMark"
                bb.AlwaysOnTop = true
                bb.ResetOnSpawn = false
                bb.Size = UDim2.fromOffset(24, 24)
                bb.StudsOffset = Vector3.new(0, 3.5, 0)
                local d = Instance.new("Frame")
                d.AnchorPoint = Vector2.new(0.5, 0.5)
                d.Position = UDim2.fromScale(0.5, 0.5)
                d.Size = UDim2.fromOffset(14, 14)
                d.Rotation = 45
                d.BackgroundColor3 = Color3.fromRGB(255, 30, 30)
                d.BorderSizePixel = 0
                d.Parent = bb
                local st = Instance.new("UIStroke")
                st.Color = Color3.new(1, 1, 1)
                st.Thickness = 2
                st.Parent = d
                bb.Parent = player:FindFirstChildOfClass("PlayerGui")
                MK.bb, MK.char = bb, nil
            end
            if MK.hl.Parent ~= cam then MK.hl.Parent = cam end
            if MK.char ~= t.char then
                MK.hl.Adornee = t.char
                MK.bb.Adornee = t.char:FindFirstChild("Head") or t.root
                MK.char = t.char
            end
            MK.hl.Enabled, MK.bb.Enabled = true, true
        end

        local function loop(myEpoch)
            local nextSlow = 0
            while S.on and S.epoch == myEpoch and _G.BFF == P do
                local now = os.clock()
                pcall(viewTick, now)
                pcall(kenTick, now)
                if CFG.PvpClean then pcall(cleanTick) elseif next(CL.off) then pcall(cleanRestore) end
                if CFG.PvpNoShake then pcall(shakeOff) elseif SH.done then pcall(shakeOn) end
                if now >= nextSlow then
                    nextSlow = now + 0.2
                    pcall(speedTick, now)
                    pcall(dashTick)
                    pcall(soruTick)
                end
                task.wait(0.1)
            end
        end

        function P.pvpSet(on)
            on = on and true or false
            CFG.Pvp = on
            if on == S.on then return end
            if on then
                if P.running then P.stop() end
                S.on = true
                S.epoch += 1
                S.faceUntil, S.lastAttack = 0, -1e9
                table.clear(S.held)
                S.lastKind, S.castTarget, S.lastKey, S.lastType = "skill", nil, nil, nil
                S.stream.last, S.stream.sent = 0, 0
                S.shots.n, S.shots.drops, S.shots.last, S.shots.tool = 0, 0, nil, nil
                S.cd.presses, S.cd.moves, S.cd.busy = 0, 0, false
                -- The life you are in has settled long ago: on at once (only
                -- a NEW life waits a moment before its view is switched on).
                V.char, V.charAt = player.Character, -1e9
                SP.char, SP.charAt = player.Character, -1e9
                pcall(cleanBaseline)
                hold(RunService.Heartbeat:Connect(function()
                    if not S.on then return end
                    local now = os.clock()
                    -- Every frame: your mouse moves fast.
                    pcall(targetTick, now)
                    pcall(markTick)
                    pcall(farTick)
                    pcall(animTick)
                    -- The game sets the view's radius to 0 when Ken ends; it
                    -- is put back before its next refresh can empty the view.
                    local om = V.om
                    if om and CFG.PvpVision then
                        local r = visionRadius()
                        if r then pcall(function() if (om.radius or 0) < r then om.radius = r end end) end
                    end
                    local want = CFG.PvpAim and S.target ~= nil
                    local gun = toolType(heldTool()) == "Gun"
                    pcall(P.pvpAimTick, want, want and gun, now)
                    -- The game's own gun snap off while you aim a gun at him,
                    -- and a ray gun's spread.
                    if want and gun then
                        pcall(snapOff)
                        SN.at = now
                        if CFG.PvpNoSpread then pcall(spreadOff, heldTool(), now) end
                    elseif SN.orig and now - SN.at > 3 then
                        pcall(snapOn)
                    end
                    if SPR.d and (not CFG.PvpNoSpread or now - SPR.at > 3) then pcall(spreadOn) end
                    pcall(shotsTick, gun and heldTool() or nil, now)
                    pcall(tuneTick, now)
                    pcall(streamTick, now)
                    pcall(cdTick)
                    local t = S.target
                    local busy = (P :: any).canCast ~= nil and not (P :: any).canCast()
                    S.faceUntil = L.faceUntil(S.faceUntil, now, next(S.held) ~= nil, busy, S.lastAttack,
                        t and t.dist, CFG.PvpFaceRange, CFG.PvpFace and t ~= nil)
                    pcall(faceNow)
                end))
                hold(RunService.Stepped:Connect(function() if S.on then pcall(faceNow) end end))
                pcall(function()
                    RunService:BindToRenderStep("BFFPvpFace", Enum.RenderPriority.Last.Value, function()
                        if S.on then pcall(faceNow) end
                    end)
                end)
                hold(UIS.InputBegan:Connect(function(i, gp)
                    if not S.on then return end
                    if i.UserInputType == Enum.UserInputType.MouseButton1 then
                        if not gp then attackPressed("M1") end          -- a click on a panel is not an attack
                    elseif ATTACK_KEYS[i.KeyCode] then
                        -- the game's own skill keys may come marked as processed:
                        -- only typing (a focused text box) is left out
                        if not UIS:GetFocusedTextBox() then attackPressed(ATTACK_KEYS[i.KeyCode]) end
                    elseif not gp and i.KeyCode == Enum.KeyCode.Q then
                        AN.qAt = os.clock()
                    end
                end))
                hold(UIS.InputEnded:Connect(function(i)
                    if i.UserInputType == Enum.UserInputType.MouseButton1 then S.held.M1 = nil
                    elseif ATTACK_KEYS[i.KeyCode] then S.held[ATTACK_KEYS[i.KeyCode]] = nil end
                end))
                task.spawn(loop, S.epoch)
                say("PvP mode on - the farm is stopped")
                print("[BFF] PvP mode on - build " .. tostring(P.build))
            else
                S.on = false
                S.epoch += 1
                for _, c in ipairs(S.conns) do pcall(function() c:Disconnect() end) end
                table.clear(S.conns)
                pcall(function() RunService:UnbindFromRenderStep("BFFPvpFace") end)
                pcall(unwrap, true)
                if V.own then pcall(V.own.destroy, V.own) V.own = nil end
                pcall(markDestroy)
                pcall(cleanRestore)
                pcall(shakeOn)
                pcall(speedRestore)
                pcall(farRestore)
                pcall(dashRestore)
                AN.animator = nil                 -- its hook went with S.conns
                table.clear(S.tune.tries)
                pcall(S.tuneSave)
                pcall(soruRestore)
                pcall(cdOff)
                pcall(snapOn)
                pcall(spreadOn)
                S.target, P.aimPart = nil, nil
                S.aimSkill, S.aimShot, S.castTarget = nil, nil, nil
                table.clear(S.hist)
                pcall(P.silentOff)
                say("PvP mode off")
                print("[BFF] PvP mode off")
            end
        end
    end
    build()
end
-- (end of pvp)

-- =========================================================
-- RACE V3 / V4
-- =========================================================
-- User, 2026-10-12 (voice): both ON by default while the script works - the
-- farm, raids, sea events, the Leviathan, any mode running, or PvP mode; the
-- script loaded and idle fires nothing (R.working). Read in the
-- game's own client (decompiled v4623):
--   V4 (Y)  Controllers/UI/RaceV4Button: not Character.RaceTransformed and
--           Character.RaceEnergy >= 1 -> RS.Events.ActivateRaceV4:Fire()
--           (the Awakening tool listens and asks the server). Both values
--           are the SERVER's - a fake-full meter is refused (2026-10-10).
--           Three public hubs call the tool's own server function instead,
--           Awakening.RemoteFunction:InvokeServer(true): the second way.
--   V3 (T)  StarterCharacterScripts/RaceAbility: with one of the seven
--           ability tools carried, T -> Remotes.CommE:FireServer(
--           "ActivateAbility"). No cooldown on the client: the server
--           decides, and nothing comes back.
-- V3 BY THE USER'S CLOCK: it cools about 29-30 s, so from the moment it is
-- SEEN going on, nothing for RaceV3Wait (28) s, then a T every RaceV3Every
-- (0.5) s until it is seen going on again - no blind spamming. Seen = the
-- game's effect "DracoRace.Roar" on Remotes.FX cast by you (Draco: a roar
-- that buffs allies and debuffs enemies for 10 s - most likely its V3,
-- Primordial Reign), or a child named after the ability put on your
-- character / HumanoidRootPart (the game's own run speed reads "Agility"
-- and "Heightened Senses" there). Your own T counts the same. Never seen
-- (another race, or the game changed): a 3 s burst after the wait, the next
-- wait counted from its end - never more than ~1 s late, never drifting.
-- While the Mirage gives you the moon (P.moonTurn), no T: yours has to find
-- V3 ready.
-- WHILE V4 IS ON the farm's fights use every weapon you carry (usedWeapons,
-- attackTick): the V4 gear "Ancient Powers" - "Upon transforming, receive
-- MAX STATS" - makes a weapon with 0 points hit like a maxed one.
-- workspace/bff_race_probe.txt: what the game put on you after the first
-- T's of a wait and when V4 went on (the first 3 of each).
-- Only P.race leaves the block.
do
    local function build()
        local R: { [string]: any } = {
            v3 = { anchor = nil, lastPress = nil, ever = false, burstStart = nil,
                seenAt = nil, seenBy = nil, presses = 0, ons = 0, note = "-", probed = false },
            v4 = { way = nil, try = nil, waitUntil = 0, fired = 0, ons = 0, refused = 0,
                on = false, onAt = nil, note = "-" },
            m1 = { name = nil, count = 0 },
            ability = nil,
            probes = {}, probeLog = {}, fxProbes = {},
            fxConn = nil, hooked = nil, hookedRoot = nil, hookConns = {},
        }
        P.race = R
        local PROBE = "bff_race_probe.txt"
        local WAYS = { event = "the game's Y", call = "the Awakening call" }

        -- RACE LOGIC (pure: tools/race_test.py runs it)
        -- The seven race-ability tools (RaceAbility's own list): T exists
        -- only while one of them is carried.
        local ABILITIES = { "Last Resort", "Agility", "Water Body", "Heavenly Blood",
            "Heightened Senses", "Energy Core", "Primordial Reign" }
        local ABILITY = {}
        for _, n in ipairs(ABILITIES) do ABILITY[n] = true end
        -- Effects (Remotes.FX) that are a V3 going on, when you cast them.
        local V3_FX = { ["DracoRace.Roar"] = true }
        local BURST = 3          -- no V3 signal ever seen: seconds of T after the wait
        -- V4's weapons, in the order their M1s take turns.
        local RANK = { Sword = 1, Melee = 2, ["Blox Fruit"] = 3, Gun = 4 }

        -- V4 now? The game's own gate (RaceV4Button), the tool that listens,
        -- alive, and a few seconds after a refusal.
        local function v4Due(alive, energy, transformed, awakening, now, waitUntil)
            return alive == true and awakening == true and transformed ~= true
                and type(energy) == "number" and energy >= 1 and now >= (waitUntil or 0)
        end

        -- THE V3 CLOCK. c.anchor = when V3 last went on (seen, or assumed at
        -- a burst's end). -> press a T now?, what it is doing.
        local function v3Step(c, now, wait, every, paused)
            if paused then return false, paused end
            if c.anchor and now < c.anchor + wait then
                return false, string.format("next T in %d s", math.ceil(c.anchor + wait - now))
            end
            if not c.ever then
                c.burstStart = c.burstStart or now
                if now - c.burstStart >= BURST then
                    c.anchor, c.burstStart = now, nil
                    return false, string.format("no V3 signal seen - on the clock, next T in %d s", math.ceil(wait))
                end
            end
            local doing = string.format("pressing T every %.1f s", every)
            if c.lastPress and now - c.lastPress < every - 1e-6 then return false, doing end
            c.lastPress = now
            return true, doing
        end
        -- V3 seen going on: the clock starts here.
        local function v3Seen(c, now, by)
            c.anchor, c.seenAt, c.seenBy, c.ever, c.burstStart = now, now, by, true, nil
        end

        -- An effect's caster is YOU? Your Player, your character, a streamed
        -- object holding one of them at [5] (Effect/Payload + EncodeObj), or a
        -- stand-in { Name, Character } (the game's fake effect player).
        local function isYou(v, me, myChar, myName)
            if v == nil then return false end
            if v == me or (myChar ~= nil and v == myChar) then return true end
            if type(v) ~= "table" then return false end
            local inner = rawget(v, 5)
            if inner ~= nil and (inner == me or (myChar ~= nil and inner == myChar)) then return true end
            local ch = rawget(v, "Character")
            if ch ~= nil and myChar ~= nil and ch == myChar then return true end
            local n = rawget(v, "Name")
            return n ~= nil and n == myName
        end
        -- Only the caster's own fields - an ally your roar buffed is in its
        -- Characters list, and so are you in an ally's.
        local CASTER = { "player", "Player", "Sender", "Caster", "Character", "Owner" }
        local function castBy(t, me, myChar, myName)
            if type(t) ~= "table" then return false end
            for i = 1, #CASTER do
                if isYou(rawget(t, CASTER[i]), me, myChar, myName) then return true end
            end
            return false
        end
        -- Remotes.FX(effectTime, meta, payload): a V3 going on, yours?
        local function fxV3(meta, payload, me, myChar, myName)
            local name = type(meta) == "table" and rawget(meta, "Name") or nil
            if type(name) ~= "string" or not V3_FX[name] then return false end
            return castBy(payload, me, myChar, myName) or castBy(meta, me, myChar, myName)
        end

        -- THE WEAPONS IN V4: every tool the game labels Sword / Melee / Blox
        -- Fruit / Gun (not the Awakening, not an ability), sword first, then
        -- the fighting style, the fruit, the gun; M1 on all; the keys keyOk
        -- allows. formPat: in a fruit's form, only that fruit (the game's rule).
        local function pickWeapons(tools, typeOf, formPat, keyOk, holdOf)
            local out = {}
            for _, t in ipairs(tools) do
                local rk = RANK[typeOf(t)]
                if rk and (formPat == nil or string.find(t.Name, formPat) ~= nil) then
                    local cfg: { [string]: any } = { use = true, M1 = true, hold = holdOf and holdOf(t.Name) or nil }
                    for _, k in ipairs(KEYS) do cfg[k] = keyOk(t.Name, k) == true end
                    table.insert(out, { name = t.Name, cfg = cfg, tool = t, rank = rk })
                end
            end
            table.sort(out, function(a, b)
                if a.rank ~= b.rank then return a.rank < b.rank end
                return a.name < b.name
            end)
            local list: any = out
            list.race = true
            return list
        end

        -- M1 IN TURN: each weapon with M1 on swings `burst` times, then the
        -- next; skip(u) = passed over (its M1 lands nowhere just now).
        local function m1Turn(T, used, burst, skip)
            local cands = {}
            for _, u in ipairs(used) do
                if u.cfg.M1 and not (skip and skip(u)) then table.insert(cands, u) end
            end
            if #cands == 0 then return nil end
            local i = nil
            for j, u in ipairs(cands) do
                if u.name == T.name then i = j break end
            end
            if not i then
                i, T.count = 1, 0
            elseif T.count >= math.max(1, math.floor(burst or 1)) then
                i, T.count = (i % #cands) + 1, 0
            end
            T.name = cands[i].name
            return cands[i]
        end
        R._t = { v4Due = v4Due, v3Step = v3Step, v3Seen = v3Seen, isYou = isYou, castBy = castBy,
            fxV3 = fxV3, pickWeapons = pickWeapons, m1Turn = m1Turn, ABILITY = ABILITY, BURST = BURST }
        -- (end of race logic)

        -- ---------- the game's values ----------
        local function raceVal(name)
            local ch = player.Character
            local v = ch and ch:FindFirstChild(name)
            return v and v.Value
        end
        function R.transformed() return raceVal("RaceTransformed") == true end
        function R.energy()
            local e = raceVal("RaceEnergy")
            return type(e) == "number" and e or nil
        end
        -- Every weapon now? V4 on and the switch on.
        function R.allNow() return CFG.RaceAll ~= false and R.transformed() end
        -- THE SCRIPT AT WORK (user, 2026-10-12: "loaded and doing nothing" =
        -- no V3, no V4): a mode running, or PvP mode on.
        function R.working() return P.running == true or CFG.Pvp == true end
        local function carried(name)
            local bp, ch = player:FindFirstChild("Backpack"), player.Character
            return (ch and ch:FindFirstChild(name)) or (bp and bp:FindFirstChild(name)) or nil
        end

        -- ---------- V4's weapons (usedWeapons) and M1s in turn (attackTick) ----------
        function R.weapons()
            local se = (P :: any).seaev
            local formPat = se and se.formOf and se.formOf() or nil
            local function keyOk(name, k)
                if k == "V" and se and se.transformFruit and se.transformFruit(name) then return false end
                if se and se.unlocked then return se.unlocked(name, k) end
                return true
            end
            local function holdOf(name)
                local w = CFG.Weapons[name]
                return w and w.hold or nil
            end
            return pickWeapons(toolNames(), toolType, formPat, keyOk, holdOf)
        end
        function R.m1Turn(used, skip) return m1Turn(R.m1, used, CFG.RaceM1Burst or 4, skip) end
        function R.m1Swung() R.m1.count += 1 end
        function R.m1Skip() R.m1.count = math.max(1, math.floor(CFG.RaceM1Burst or 4)) end

        -- ---------- the probe ----------
        local function probeLine(s)
            table.insert(R.probeLog, os.date("%Y-%m-%d %H:%M:%S  ") .. s)
            while #R.probeLog > 200 do table.remove(R.probeLog, 1) end
            if writefile then pcall(writefile, PROBE, table.concat(R.probeLog, "\n")) end
        end
        -- What the game puts on you for `secs`: children and attributes of the
        -- character and its HumanoidRootPart, and the effects that arrive
        -- (yours marked). The first 3 of each kind.
        local function probe(kind, secs, why)
            local n = (R.probes[kind] or 0) + 1
            R.probes[kind] = n
            if n > 3 then return end
            local ch = player.Character
            if not ch then return end
            local root = ch:FindFirstChild("HumanoidRootPart")
            local list, seen, conns = {}, {}, {}
            local function add(s)
                if seen[s] or #list >= 40 then return end
                seen[s] = true
                table.insert(list, s)
            end
            local function watch(obj, label)
                if not obj then return end
                table.insert(conns, obj.ChildAdded:Connect(function(x)
                    add(string.format("%s + %s (%s)", label, x.Name, x.ClassName))
                end))
                table.insert(conns, obj.AttributeChanged:Connect(function(a)
                    add(string.format("%s attribute %s = %s", label, tostring(a), tostring(obj:GetAttribute(a))))
                end))
            end
            watch(ch, "character")
            watch(root, "root")
            local function onFx(name, mine) add("effect " .. tostring(name) .. (mine and " (YOURS)" or "")) end
            R.fxProbes[onFx] = true
            task.delay(secs, function()
                for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
                R.fxProbes[onFx] = nil
                local line = string.format("[%s #%d] %s: %s", kind, n, why,
                    (#list > 0) and table.concat(list, "  ;  ") or "nothing new")
                probeLine(line)
                print("[BFF] race probe " .. line)
            end)
        end

        -- ---------- V3 going on, seen ----------
        local function seenV3(by)
            local c, now = R.v3, os.clock()
            -- one going-on can show twice (its effect and its child)
            if c.seenAt and now - c.seenAt < 5 then return end
            v3Seen(c, now, by)
            c.ons += 1
            if c.ons <= 3 then print("[BFF] race: V3 on (" .. tostring(by) .. ")") end
        end
        local function unhookChar()
            for _, c in ipairs(R.hookConns) do pcall(function() c:Disconnect() end) end
            table.clear(R.hookConns)
            R.hooked, R.hookedRoot = nil, nil
        end
        local function hookChar(ch, root)
            unhookChar()
            R.hooked, R.hookedRoot = ch, root
            local function watch(obj)
                if not obj then return end
                table.insert(R.hookConns, obj.ChildAdded:Connect(function(x)
                    if _G.BFF ~= P then return end
                    -- an ability TOOL put in your hand is not the ability on
                    if ABILITY[x.Name] and not x:IsA("Tool") then seenV3(x.Name) end
                end))
            end
            watch(ch)
            watch(root)
        end
        -- One more listener on the game's effect remote (no hook): a V3
        -- going on, and what a probe wants to see.
        local function hookFX()
            if R.fxConn then return end
            local rem = RS:FindFirstChild("Remotes")
            local fx = rem and rem:FindFirstChild("FX")
            if not (fx and fx:IsA("RemoteEvent")) then return end
            R.fxConn = fx.OnClientEvent:Connect(function(_, meta, payload)
                if _G.BFF ~= P then return end
                local name = type(meta) == "table" and rawget(meta, "Name") or nil
                if type(name) ~= "string" then return end
                local v3 = V3_FX[name] == true
                if not v3 and next(R.fxProbes) == nil then return end
                local ch = player.Character
                local mine = castBy(payload, player, ch, player.Name) or castBy(meta, player, ch, player.Name)
                for fn in pairs(R.fxProbes) do pcall(fn, name, mine) end
                if v3 and mine then seenV3(name) end
            end)
        end

        -- ---------- V4 ----------
        local function fireV4(way, aw, now, tried)
            tried = tried or {}
            tried[way] = true
            local sent = false
            if way == "event" then
                local evs = RS:FindFirstChild("Events")
                local ev = evs and evs:FindFirstChild("ActivateRaceV4")
                if ev and ev:IsA("BindableEvent") then
                    sent = pcall(function() ev:Fire() end)
                end
            else
                local rf = aw and aw:FindFirstChild("RemoteFunction")
                if rf and rf:IsA("RemoteFunction") then
                    sent = true
                    task.spawn(function() pcall(function() rf:InvokeServer(true) end) end)
                end
            end
            local s = R.v4
            -- not found = the other way at once, no 1.5 s wait for nothing
            s.try = { way = way, at = sent and now or (now - 1.5), tried = tried }
            s.fired += 1
            s.note = "meter full - " .. WAYS[way] .. (sent and "" or " (not found)")
        end
        local function v4Tick(now, alive)
            local s = R.v4
            local tr = R.transformed()
            if tr and not s.on then
                s.on, s.onAt, s.ons = true, now, s.ons + 1
                local how = s.try and WAYS[s.try.way] or "your own Y"
                if s.try then s.way = s.try.way end
                s.try = nil
                s.note = "on - " .. how
                print("[BFF] race: V4 on - " .. how)
                probe("v4", 2, "V4 went on (" .. how .. ")")
            elseif s.on and not tr then
                s.on = false
                print(string.format("[BFF] race: V4 over after %d s", math.floor(now - (s.onAt or now))))
            end
            if tr then return end
            if CFG.RaceV4 == false then
                s.try, s.note = nil, "off"
                return
            end
            if not R.working() then
                s.try, s.note = nil, "waits - nothing running (a mode, or PvP)"
                return
            end
            local aw = carried("Awakening")
            if s.try then
                if now - s.try.at < 1.5 then return end
                local other = (s.try.way == "event") and "call" or "event"
                if alive and aw and not s.try.tried[other] then
                    fireV4(other, aw, now, s.try.tried)
                    return
                end
                s.try = nil
                s.refused += 1
                s.waitUntil = now + 3
                s.note = "meter full but no transform (both ways tried) - again in 3 s"
                if s.refused <= 3 then print("[BFF] race: V4 refused - " .. s.note) end
                return
            end
            local e = R.energy()
            if v4Due(alive, e, tr, aw ~= nil, now, s.waitUntil) then
                fireV4(s.way or "event", aw, now, nil)
            elseif not aw then
                s.note = "no Awakening tool - V4 not unlocked"
            elseif e == nil then
                s.note = "no meter on your character"
            elseif e < 1 then
                s.note = "fires when it is full"
            end
        end

        -- ---------- V3 ----------
        local function v3Tick(now, alive)
            local c = R.v3
            if CFG.RaceV3 == false then
                c.note = "off"
                return
            end
            R.ability = nil
            for _, n in ipairs(ABILITIES) do
                local t = carried(n)
                if t and t:IsA("Tool") then R.ability = n break end
            end
            if not R.ability then
                c.note = "no race ability tool - V3 not unlocked"
                return
            end
            local paused = nil
            if not R.working() then
                paused = "waits - nothing running (a mode, or PvP)"
            elseif not alive then
                paused = "waiting for your character"
            elseif P.handsOff and P.moonTurn and now - P.moonTurn < 2 then
                paused = "your turn at the moon - your own T"
            end
            local anchorWas = c.anchor
            local go, why = v3Step(c, now, tonumber(CFG.RaceV3Wait) or 28, tonumber(CFG.RaceV3Every) or 0.5, paused)
            c.note = why
            if not go then return end
            local rem = RS:FindFirstChild("Remotes")
            local ce = rem and rem:FindFirstChild("CommE")
            if not ce then
                c.note = "no CommE remote"
                return
            end
            pcall(function() ce:FireServer("ActivateAbility") end)
            c.presses += 1
            -- the first T after a wait: what does the game put on you?
            if c.probed ~= (anchorWas or -1) then
                c.probed = anchorWas or -1
                probe("v3", 3.5, "the T's after a wait")
            end
        end

        -- ---------- every 0.1 s, from load ----------
        function R.tick()
            local now = os.clock()
            local ch = player.Character
            local root = ch and ch:FindFirstChild("HumanoidRootPart")
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            local alive = root ~= nil and hum ~= nil and hum.Health > 0
            if ch ~= R.hooked or root ~= R.hookedRoot then hookChar(ch, root) end
            hookFX()
            local ok, err = pcall(v4Tick, now, alive)
            if not ok then R.v4.note = "error: " .. tostring(err) end
            ok, err = pcall(v3Tick, now, alive)
            if not ok then R.v3.note = "error: " .. tostring(err) end
        end
        function R.unhook()
            unhookChar()
            if R.fxConn then pcall(function() R.fxConn:Disconnect() end) end
            R.fxConn = nil
        end

        -- ---------- the panel's lines ----------
        function R.text()
            local s, c, now = R.v4, R.v3, os.clock()
            local e = R.energy()
            local pct = e and string.format("meter %d %%", math.floor(e * 100 + 0.5)) or "no meter"
            local v4
            if R.transformed() then
                local names = {}
                if CFG.RaceAll ~= false then
                    for _, u in ipairs(R.weapons()) do table.insert(names, u.name) end
                end
                v4 = string.format("V4 ON %d s  ·  %s%s", math.floor(now - (s.onAt or now)), pct,
                    (#names > 0) and ("\n   every weapon: " .. table.concat(names, ", ")) or "")
            elseif CFG.RaceV4 == false then
                v4 = "V4 off"
            else
                v4 = "V4  " .. pct .. "  ·  " .. tostring(s.note)
            end
            local v3
            if CFG.RaceV3 == false then
                v3 = "V3 off"
            elseif not R.ability then
                v3 = "V3  " .. tostring(c.note)
            elseif c.ever and c.seenAt then
                v3 = string.format("V3 on %d s ago (%s)  ·  %s", math.floor(now - c.seenAt), tostring(c.seenBy), tostring(c.note))
            else
                v3 = string.format("V3  %s  ·  %d T sent  ·  no V3 signal seen yet", tostring(c.note), c.presses)
            end
            return v4 .. "\n" .. v3
        end
    end
    build()
end
-- (end of race)

-- =========================================================
-- SETTINGS LOCK
-- =========================================================
-- User, 2026-10-14: "if I customize a setting and lock it, I want it to stay
-- - even after I reload the script". Locked = every setting you CHANGED from
-- the defaults (P.cfgDefaults) goes to your executor's workspace folder,
-- bff_settings_<your UserId>.json - at once, then within 2 s of any change -
-- and comes back at every load, before the panel is built (a hop's carried
-- settings still go over it). Only what you changed: a default changed in a
-- later build still reaches everything you never touched. Off = the file
-- says unlocked; the next load starts from the defaults.
do
    local function build()
        local HttpService = game:GetService("HttpService")

        -- SETTINGS LOGIC (pure: tools/lock_test.py)
        local LK = {}
        -- A value a JSON file keeps as it is: a number, a string, true /
        -- false, or a table of those under string keys or as a list.
        function LK.plain(v)
            local t = type(v)
            if t == "boolean" or t == "string" then return true end
            if t == "number" then return v == v and v ~= math.huge and v ~= -math.huge end
            if t ~= "table" then return false end
            local strKeys, numKeys = false, false
            for k, x in pairs(v) do
                if type(k) == "string" then strKeys = true
                elseif type(k) == "number" and k >= 1 and k % 1 == 0 then numKeys = true
                else return false end
                if not LK.plain(x) then return false end
            end
            return not (strKeys and numKeys)
        end
        function LK.copy(v)
            if type(v) ~= "table" then return v end
            local t = {}
            for k, x in pairs(v) do t[k] = LK.copy(x) end
            return t
        end
        function LK.same(a, b)
            if type(a) ~= type(b) then return false end
            if type(a) ~= "table" then return a == b end
            for k, x in pairs(a) do
                if not LK.same(x, b[k]) then return false end
            end
            for k in pairs(b) do
                if a[k] == nil then return false end
            end
            return true
        end
        -- What you changed: every plain setting not the same as its default.
        function LK.diff(cfg, def)
            local out = {}
            for k, v in pairs(cfg) do
                if LK.plain(v) and not LK.same(v, def[k]) then out[k] = LK.copy(v) end
            end
            return out
        end
        -- Yours back over the defaults. A setting whose kind changed in a
        -- later build (a number now a switch) is left at its new default; a
        -- table is laid over the default one key by key (a key the new build
        -- added keeps its default), a list replaces it. -> how many came back.
        local function lay(dst, src)
            for k, x in pairs(src) do
                if type(x) == "table" and type(dst[k]) == "table" and #x == 0 then
                    lay(dst[k], x)
                else
                    dst[k] = LK.copy(x)
                end
            end
            return dst
        end
        function LK.apply(cfg, saved, def)
            local n = 0
            for k, sv in pairs(saved) do
                local dv = def[k]
                if dv == nil or type(dv) == type(sv) then
                    if type(sv) == "table" and type(dv) == "table" and #sv == 0 then
                        cfg[k] = lay(LK.copy(dv), sv)
                    else
                        cfg[k] = LK.copy(sv)
                    end
                    n += 1
                end
            end
            return n
        end
        -- (end of settings logic)

        local FILE = "bff_settings_" .. tostring(player.UserId) .. ".json"
        local K = { on = false, note = "off - a reload starts from the defaults", last = nil, LK = LK }
        P.lock = K

        local function save(force)
            local d = LK.diff(CFG, P.cfgDefaults)
            local ok, s = pcall(function()
                return HttpService:JSONEncode({ v = 1, locked = true, build = P.build, cfg = d })
            end)
            if not ok then K.note = "locked, but your settings would not go into the file" return end
            if s == K.last and not force then return end
            if not (writefile and pcall(writefile, FILE, s)) then
                K.note = "locked, but this executor cannot write a file - NOT kept"
                return
            end
            K.last = s
            local n = 0
            for _ in pairs(d) do n += 1 end
            K.note = string.format("locked  ·  %d you changed, kept  ·  saved %s", n, os.date("%H:%M:%S"))
        end
        function P.lockSet(on)
            K.on = on and true or false
            if K.on then
                save(true)
            else
                if writefile then pcall(writefile, FILE, '{"v":1,"locked":false}') end
                K.last = nil
                K.note = "off - the next load starts from the defaults (this one keeps what you set)"
            end
        end

        -- At load: your locked settings back.
        local okR, s = pcall(function() return readfile and isfile and isfile(FILE) and readfile(FILE) end)
        if okR and type(s) == "string" then
            local okD, t = pcall(function() return HttpService:JSONDecode(s) end)
            if okD and type(t) == "table" and t.locked == true and type(t.cfg) == "table" then
                local n = LK.apply(CFG, t.cfg, P.cfgDefaults)
                K.on, K.last = true, nil
                K.note = string.format("locked  ·  %d of your settings back from your file", n)
                print("[BFF] settings lock: " .. n .. " of your settings back (" .. FILE .. ")")
            end
        end
        task.spawn(function()
            while _G.BFF == P do
                task.wait(2)
                if K.on then pcall(save, false) end
            end
        end)
    end
    build()
end
-- (end of settings lock)

-- Arrived by an elite hunt's hop: its settings back, and the hunt goes on.
do
    local resumed = false
    pcall(function() resumed = P.takeCarry() end)
    -- The team AFTER the carried settings: the one you picked, not the default.
    task.spawn(function() pcall(P.pickTeam) end)
    pcall(syncWeapons)
    say(resumed and ("elite hunt carried over (" .. tostring(P.elite.carried) .. ")")
        or "loaded - pick targets, then press Start")
    P.panel()
    if resumed then task.defer(P.start)
    elseif CFG.Pvp then CFG.Pvp = false task.defer(P.pvpSet, true) end
end
-- Water is land from load, farm running or not (farm_pro's, unchanged).
task.spawn(function()
    while _G.BFF == P do
        pcall(keepWater)
        task.wait(0.25)
    end
end)
-- ROUTES: every portal pad that streams in is kept (its spot, its Pivot), farm
-- running or not - the next long trip knows it.
task.spawn(function()
    while _G.BFF == P do
        pcall(function() P.route.scan() end)
        task.wait(3)
    end
end)
-- The server news: one look a second from load, farm running or not.
task.spawn(function()
    while _G.BFF == P do
        pcall(P.news.tick)
        task.wait(1)
    end
end)
-- Race V3 / V4 (RACE): watched from load; fired only while a mode runs or PvP is on.
task.spawn(function()
    while _G.BFF == P do
        pcall(P.race.tick)
        task.wait(0.1)
    end
    pcall(P.race.unhook)
end)
do
    local deepConn
    deepConn = RunService.Heartbeat:Connect(function()
        if _G.BFF ~= P then
            deepConn:Disconnect()
            parkFloor()
            return
        end
        pcall(deepTick)
    end)
end
print("[BFF] loaded. Use the panel, or _G.BFF.start()")
